/// Result of evaluating a jq expression.
#[derive(Debug)]
pub enum QueryResult<'a, W = Vec<u64>> {
    /// Single value result (reference to original JSON).
    One(StandardJson<'a, W>),

    /// Single cursor result (for unchanged container values).
    ///
    /// This is more efficient than `One` for arrays/objects because
    /// it preserves the cursor, allowing direct output of raw bytes
    /// without decomposing into individual element cursors.
    OneCursor(JsonCursor<'a, W>),

    /// Multiple values (from iteration).
    Many(Vec<StandardJson<'a, W>>),

    /// No result (optional that was missing).
    None,

    /// Error during evaluation.
    Error(EvalError),

    /// Single owned value (from construction/computation).
    Owned(OwnedValue),

    /// Multiple owned values.
    ManyOwned(Vec<OwnedValue>),

    /// Break from a labeled scope.
    /// Contains the label name to match against enclosing Label expressions.
    Break(String),

    /// `halt`/`halt_error(n)`: exit the whole process with this code (#791).
    /// Not caught by `try`/`catch` or `label`/`break`, unlike `Error`/`Break`.
    Halt(i32),

    /// One or more outputs were produced before the stream terminated in an
    /// error, a `break`, or a `halt` (#400, #494, #791).
    ///
    /// `Error`/`Break`/`Halt` remain the zero-prefix case — every terminal
    /// raise deep in a builtin still constructs them directly, unchanged. The
    /// prefix is always non-empty by construction (see `partial`); an empty
    /// prefix normalizes to bare `Error`/`Break`/`Halt`.
    Partial(Vec<OwnedValue>, Control),
}

impl<W: Clone + AsRef<[u64]>> QueryResult<'_, W> {
    /// Convert OneCursor to One by materializing the cursor value.
    /// Used internally when we need StandardJson from a result.
    #[inline]
    fn materialize_cursor(self) -> Self {
        match self {
            QueryResult::OneCursor(c) => QueryResult::One(c.value()),
            other => other,
        }
    }

    /// Returns true if this result is an evaluation error.
    ///
    /// A `Partial` prefix followed by an error still counts — this answers
    /// "did evaluating this end in an error," not "did it produce nothing."
    ///
    /// Mirrors [`crate::jq::eval_generic::GenericResult::is_error`] so the two
    /// evaluators can be compared directly in tests.
    pub fn is_error(&self) -> bool {
        matches!(
            self,
            QueryResult::Error(_) | QueryResult::Partial(_, Control::Error(_))
        )
    }

    /// Collect all output values into a `Vec<OwnedValue>`.
    ///
    /// Mirrors [`crate::jq::eval_generic::GenericResult::collect_owned`]:
    /// `None`, `Error`, and `Break` collect to an empty `Vec`. A `Partial`
    /// collects its prefix — the whole point of #400/#494 is that those
    /// outputs are no longer discarded. This gives the full evaluator the
    /// same materialization surface as the generic (CLI) path, which is what
    /// evaluator-parity tests rely on.
    pub fn collect_owned(self) -> Vec<OwnedValue> {
        match self {
            QueryResult::One(v) => vec![to_owned(&v)],
            QueryResult::OneCursor(c) => vec![to_owned(&c.value())],
            QueryResult::Many(vs) => vs.iter().map(to_owned).collect(),
            QueryResult::None => Vec::new(),
            QueryResult::Error(_) => Vec::new(),
            QueryResult::Owned(o) => vec![o],
            QueryResult::ManyOwned(os) => os,
            QueryResult::Break(_) => Vec::new(),
            QueryResult::Halt(_) => Vec::new(),
            QueryResult::Partial(vs, _control) => vs,
        }
    }
}

// `EvalError` and the jq-compatible wording of its messages live in
// `super::error` (#356), so both evaluators construct errors from one
// vocabulary instead of inlining format strings at each raise site.
//
// The kind helpers below stay here: they are about values, not messages,
// and `super::error` renders whatever it is handed.
pub use super::error::{BinOp, Control, EvalError, EvalEscape};

impl<W> From<EvalEscape> for QueryResult<'_, W> {
    fn from(escape: EvalEscape) -> Self {
        match escape {
            EvalEscape::Error(e) => QueryResult::Error(e),
            EvalEscape::Break(label) => QueryResult::Break(label),
            EvalEscape::Halt(code) => QueryResult::Halt(code),
        }
    }
}

impl<W> From<EvalError> for QueryResult<'_, W> {
    fn from(e: EvalError) -> Self {
        QueryResult::Error(e)
    }
}

// jq's `jv_kind` discriminants, verbatim from `jv.h`, so the two enums can be
// read side by side. `JV_KIND_INVALID` (0) has no `OwnedValue` counterpart — an
// `OwnedValue` is always a valid value — so the numbering starts at 1.
const JQ_KIND_NULL: u8 = 1;
const JQ_KIND_FALSE: u8 = 2;
const JQ_KIND_TRUE: u8 = 3;
const JQ_KIND_NUMBER: u8 = 4;
const JQ_KIND_STRING: u8 = 5;
const JQ_KIND_ARRAY: u8 = 6;
const JQ_KIND_OBJECT: u8 = 7;

/// A value's kind as jq's `jv_get_kind` reports it, for the operand screens that
/// compare kinds rather than type names.
///
/// This is a *finer* partition than [`OwnedValue::type_name`]: jq's `jv_kind`
/// enum has separate `JV_KIND_FALSE` and `JV_KIND_TRUE`, and only `jv_kind_name`
/// collapses the pair back to the one word `boolean`. `f_contains` screens on
/// `jv_get_kind`, so jq errors on `true | contains(false)` — with a message that
/// calls *both* operands `boolean` — while `true | contains(true)` is a plain
/// `true`. Screening on `type_name` instead answers `false` for that pair, which
/// is exactly the divergence #358 is about (#358 review).
///
/// This is the one definition of "what kind is this value" in the jq module;
/// [`sort_rank`] is derived from it rather than matched independently. Only
/// equality is ever asked of the value here — orderings go through `sort_rank`.
fn jq_kind(value: &OwnedValue) -> u8 {
    match value {
        OwnedValue::Null => JQ_KIND_NULL,
        OwnedValue::Bool(false) => JQ_KIND_FALSE,
        OwnedValue::Bool(true) => JQ_KIND_TRUE,
        // jq has one number kind; `1 | contains(1.0)` is a comparison, not an error.
        OwnedValue::Int(_) | OwnedValue::Float(_) | OwnedValue::NumberLiteral(..) => JQ_KIND_NUMBER,
        OwnedValue::String(_) => JQ_KIND_STRING,
        OwnedValue::Array(_) => JQ_KIND_ARRAY,
        OwnedValue::Object(_) => JQ_KIND_OBJECT,
    }
}

/// A value's rank in jq's sort order:
/// `null < false < true < number < string < array < object`.
///
/// This is [`jq_kind`]'s partition with the two boolean kinds merged into the
/// single `boolean` slot `jv_kind_name` reports — which is what every *ordering*
/// caller wants (`sort`, `min`, `max`, `unique`, `group_by`, the comparison
/// operators, `bsearch`). Only `contains`/`inside` need the finer `jq_kind`.
///
/// Derived rather than matched so the two cannot drift: before #358 there were
/// three hand-written copies of this table in the jq module, and a fourth would
/// have arrived with the containment screen. See the #106 lesson in `CLAUDE.md`
/// — one definition, plus a test that the call sites agree
/// (`sort_rank_agrees_with_jq_kind`).
pub(crate) fn sort_rank(value: &OwnedValue) -> u8 {
    let kind = jq_kind(value);
    // Shift off the unused `JV_KIND_INVALID` slot, then close the gap that
    // merging `false` and `true` into one rank leaves behind.
    kind - 1 - u8::from(kind >= JQ_KIND_TRUE)
}

/// Get the type name of a JSON value for error messages.
fn type_name<W>(value: &StandardJson<'_, W>) -> &'static str {
    match value {
        StandardJson::Object(_) => "object",
        StandardJson::Array(_) => "array",
        StandardJson::String(_) => "string",
        StandardJson::Number(_) => "number",
        StandardJson::Bool(_) => "boolean",
        StandardJson::Null => "null",
        StandardJson::Error(_) => "error",
    }
}

/// Convert a StandardJson value to an OwnedValue.
fn to_owned<W: Clone + AsRef<[u64]>>(value: &StandardJson<'_, W>) -> OwnedValue {
    match value {
        StandardJson::Null => OwnedValue::Null,
        StandardJson::Bool(b) => OwnedValue::Bool(*b),
        StandardJson::Number(n) => {
            if is_nan_sentinel(n.raw_bytes()) {
                OwnedValue::Float(f64::NAN)
            } else {
                match core::str::from_utf8(n.raw_bytes()) {
                    Ok(s) => OwnedValue::from_number_literal(s),
                    // Fallback - shouldn't happen for valid JSON
                    Err(_) => OwnedValue::Float(0.0),
                }
            }
        }
        StandardJson::String(s) => {
            if let Ok(cow) = s.as_str() {
                OwnedValue::String(cow.into_owned())
            } else {
                OwnedValue::String(String::new())
            }
        }
        StandardJson::Array(elements) => {
            let items: Vec<OwnedValue> = (*elements).map(|e| to_owned(&e)).collect();
            OwnedValue::Array(items)
        }
        StandardJson::Object(fields) => {
            let mut map = IndexMap::new();
            for field in *fields {
                // Get the key as a string
                if let StandardJson::String(key_str_val) = field.key() {
                    if let Ok(cow) = key_str_val.as_str() {
                        map.insert(cow.into_owned(), to_owned(&field.value()));
                    }
                }
            }
            OwnedValue::Object(map)
        }
        StandardJson::Error(_) => OwnedValue::Null,
    }
}

/// Materialize a key/slice-bound candidate just enough to classify it.
///
/// `index_one`/[`EvalError::cannot_index`] and `SliceBounds::resolved_bound`
/// never inspect an Array/Object candidate's *contents* — only its type
/// name, to build the `Cannot index ... with array/object`/`Array or string
/// slice indices must be integers` message — so a full recursive [`to_owned`]
/// of a large navigated container candidate is pure waste when it can only
/// ever be rejected on type. Mirrors [`json_is_truthy`]'s existing "classify
/// without paying for `to_owned`'s full deep copy" idiom, for the same
/// reason: `.. | .[.k]?` visits every node in a tree, and on a
/// linear-nesting document `.k`'s value at depth *i* is the entire
/// remaining subtree (#626).
fn to_owned_key_shape<W: Clone + AsRef<[u64]>>(value: &StandardJson<'_, W>) -> OwnedValue {
    match value {
        StandardJson::Array(_) => OwnedValue::Array(Vec::new()),
        StandardJson::Object(_) => OwnedValue::Object(IndexMap::new()),
        other => to_owned(other),
    }
}

/// jq truthiness of a borrowed value: everything except `null` and `false`.
///
/// Equivalent to `to_owned(value).is_truthy()` — [`to_owned`] maps
/// `StandardJson::Error` to `OwnedValue::Null`, which is falsy — but O(1)
/// where `to_owned` deep-copies whole arrays and objects to answer a yes/no
/// question. That matters for the stream operators, which test *every* output
/// rather than just the first.
fn json_is_truthy<W>(value: &StandardJson<'_, W>) -> bool {
    !matches!(
        value,
        StandardJson::Null | StandardJson::Bool(false) | StandardJson::Error(_)
    )
}

/// Check if an expression contains PathNoArg, Parent, or Key builtins that need path context.
pub(crate) fn needs_path_context(expr: &Expr) -> bool {
    match expr {
        Expr::Builtin(Builtin::PathNoArg) => true,
        Expr::Builtin(Builtin::Parent) => true,
        Expr::Builtin(Builtin::ParentN(_)) => true,
        Expr::Builtin(Builtin::Key) => true,
        // `--eval-all`'s `file_index`/`fileIndex`/`fi` (#715) needs the same
        // path-context routing as `Key` above -- it resolves via
        // `current_path`, not a cursor.
        Expr::Builtin(Builtin::FileIndex) => true,
        // Neither `Compare` nor `Select` carries path context on its own,
        // but a `key`/`document_index`/`file_index` nested in one of their
        // operands does -- e.g. `select(file_index == 0)`, the headline
        // `--eval-all` idiom. Recursing here is what makes
        // `eval_pipe`/`eval_pipe_with_path_context_internal` route the whole
        // pipe through path-context evaluation instead of losing it (#715;
        // this closes a pre-existing gap for `key`/`document_index` too,
        // e.g. `.[] | select(key >= 1)` previously produced no output).
        Expr::Compare { left, right, .. } => needs_path_context(left) || needs_path_context(right),
        // `*`-merge (`select(file_index==0) * select(file_index==1)`) is the
        // other headline `--eval-all` idiom (#715) -- both operands need the
        // same recursion as `Compare` above.
        Expr::Arithmetic { left, right, .. } => {
            needs_path_context(left) || needs_path_context(right)
        }
        Expr::Builtin(Builtin::Select(cond)) => needs_path_context(cond),
        // `map(f)` needs the same recursion as `Select` above -- e.g.
        // `map(select(file_index == 0))`, previously silently stubbed to 0
        // for every element instead of resolving or erroring (#715
        // follow-up).
        Expr::Builtin(Builtin::Map(f)) => needs_path_context(f),
        Expr::Pipe(exprs) => exprs.iter().any(needs_path_context),
        Expr::Paren(inner) => needs_path_context(inner),
        Expr::Optional(inner) => needs_path_context(inner),
        Expr::Comma(exprs) => exprs.iter().any(needs_path_context),
        Expr::IndexExpr { target, key } => needs_path_context(target) || needs_path_context(key),
        Expr::SliceExpr { target, start, end } => {
            needs_path_context(target)
                || start.as_deref().is_some_and(needs_path_context)
                || end.as_deref().is_some_and(needs_path_context)
        }
        Expr::If {
            cond,
            then_branch,
            else_branch,
        } => {
            needs_path_context(cond)
                || needs_path_context(then_branch)
                || needs_path_context(else_branch)
        }
        Expr::Try { expr, catch } => {
            needs_path_context(expr) || catch.as_ref().is_some_and(|c| needs_path_context(c))
        }
        // `label $x | ...` is otherwise inert wrt path context, but a
        // `key`/`document_index`/`file_index` inside its body still needs
        // the same recursion as `If`/`Try` above -- without it,
        // `label $out | file_index` silently dropped path context (#715
        // follow-up).
        Expr::Label { body, .. } => needs_path_context(body),
        _ => false,
    }
}

/// Evaluate a single expression against a JSON value.
fn eval_single<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    match expr {
        Expr::Identity => QueryResult::One(value),

        Expr::Field(name) => index_object_by_name::<W>(value, name, optional),

        Expr::Index(idx) => index_array_by_position::<W>(value, *idx, optional),

        Expr::IndexExpr { target, key } => eval_index_expr::<W, S>(target, key, value, optional),

        Expr::SliceExpr { target, start, end } => {
            eval_slice_expr::<W, S>(target, start, end, value, optional)
        }

        Expr::Slice { start, end } => match value {
            StandardJson::Array(elements) => {
                // Fast path: full slice [:] / [0:] returns the original array unchanged
                if matches!(start, None | Some(0)) && end.is_none() {
                    return QueryResult::One(value);
                }
                // jq array slicing yields a single sub-array, not a stream of elements
                let items: Vec<OwnedValue> = slice_elements::<W>(elements, *start, *end)
                    .iter()
                    .map(to_owned)
                    .collect();
                QueryResult::Owned(OwnedValue::Array(items))
            }
            // jq returns null for slice on null
            StandardJson::Null => QueryResult::One(StandardJson::Null),
            // jq supports string slicing
            StandardJson::String(s) => {
                let s_str = match s.as_str() {
                    Ok(s) => s,
                    Err(_) => return QueryResult::Error(EvalError::new("invalid UTF-8 in string")),
                };

                // Fast path: identity slice [:] returns original string without character counting
                if start.is_none() && end.is_none() {
                    return QueryResult::One(value);
                }

                // Fast path: [0:] on non-empty string returns original
                if let Some(0) = start {
                    if end.is_none() && !s_str.is_empty() {
                        return QueryResult::One(value);
                    }
                }

                // Only count characters when actually slicing. jq indexes a
                // string slice by character, so the length handed to `resolve`
                // is a character count — the bound arithmetic is the same
                // either way.
                let len = s_str.chars().count();
                let range = SliceBounds::from_literals(*start, *end).resolve(len);

                // Fast path: if the resolved slice is the whole string, return
                // the original rather than rebuilding it.
                if range == (0..len) {
                    return QueryResult::One(value);
                }

                QueryResult::Owned(OwnedValue::String(slice::slice_str(&s_str, range)))
            }
            _ if optional => QueryResult::None,
            // jq models `.[a:b]` as indexing with `{"start":a,"end":b}`, so a
            // slice of a non-sliceable value reports an *object* key.
            _ => QueryResult::Error(EvalError::cannot_index_with_type(
                type_name(&value),
                "object",
            )),
        },

        Expr::Iterate => match value {
            StandardJson::Array(elements) => {
                let results: Vec<_> = elements.collect();
                QueryResult::Many(results)
            }
            StandardJson::Object(fields) => {
                let results: Vec<_> = fields.map(|f| f.value()).collect();
                QueryResult::Many(results)
            }
            _ if optional => QueryResult::None,
            _ => QueryResult::Error(EvalError::cannot_iterate(&to_owned(&value))),
        },

        // `.[EXPR]?`/`.[S:E]?`: jq's `?` here guards only the *final*
        // indexing/slicing operation, not evaluation of the bracket's own
        // key/bounds sub-expression — verified against jq 1.7.1:
        // `echo '"a"' | jq '.[.k]?'` still raises (exit 5, "Cannot index
        // string with string \"k\""), even though the whole `.[.k]` is
        // syntactically inside the `?`. Wrapping in one more layer (a paren,
        // a pipe stage, or plain `try`) *does* catch it — `jq '(.[.k])?'`,
        // `jq '(.[.k] | .+1)?'`, and `jq 'try .[.k]'` all exit 0 — so this is
        // specific to the bare bracket-then-`?` postfix form, which is the
        // only shape that reaches here (that form and no other parses
        // straight to `Expr::Optional(Expr::IndexExpr { .. })` /
        // `Expr::Optional(Expr::SliceExpr { .. })`; every other spelling
        // interposes a `Paren`/`Pipe`/`Try` node this arm doesn't match).
        // `eval_index_expr`/`eval_slice_expr` already implement this split
        // (they evaluate the key/bounds with a hardcoded `optional: false`
        // and only consult the ambient `optional` for their own final
        // index/slice step), so preserve the direct "just forward
        // `optional`, don't wrap in a catch" dispatch here — routing it
        // through `eval_try` below like every other expression would catch
        // the key/bounds error too, which is too broad.
        Expr::Optional(inner)
            if matches!(**inner, Expr::IndexExpr { .. } | Expr::SliceExpr { .. }) =>
        {
            eval_single::<W, S>(inner, value, true)
        }

        // `E?` is sugar for `try E` (no catch handler): evaluate `inner`
        // with the ambient `optional` — not forced `true` — so nested
        // leaves raise real errors instead of each independently
        // self-suppressing, and let `eval_try`'s existing catch-once logic
        // decide whether to swallow the *aggregate* result. Forcing
        // `optional = true` down the whole subtree (the old behavior) let a
        // masked error inside a combinator (comma, reduce/foreach/while/
        // until) look exactly like ordinary `empty` to that combinator,
        // which then wrongly kept going instead of stopping (#693).
        Expr::Optional(inner) => eval_try::<W, S>(inner, None, value, optional),

        Expr::Pipe(exprs) => eval_pipe::<W, S>(exprs, value, optional),

        Expr::Comma(exprs) => eval_comma::<W, S>(exprs, value, optional),

        Expr::Array(inner) => eval_array_construction::<W, S>(inner, value, optional),

        Expr::Object(entries) => eval_object_construction::<W, S>(entries, value, optional),

        Expr::Literal(lit) => QueryResult::Owned(literal_to_owned(lit)),

        Expr::RecursiveDescent => eval_recursive_descent::<W, S>(value),

        Expr::Paren(inner) => eval_single::<W, S>(inner, value, optional),

        Expr::Arithmetic { op, left, right } => {
            eval_arithmetic::<W, S>(*op, left, right, value, optional)
        }

        Expr::Compare { op, left, right } => {
            eval_compare::<W, S>(*op, left, right, value, optional)
        }

        Expr::And(left, right) => eval_and::<W, S>(left, right, value, optional),

        Expr::Or(left, right) => eval_or::<W, S>(left, right, value, optional),

        Expr::Not => eval_not::<W>(value),

        Expr::Alternative(left, right) => eval_alternative::<W, S>(left, right, value, optional),

        Expr::If {
            cond,
            then_branch,
            else_branch,
        } => eval_if::<W, S>(cond, then_branch, else_branch, value, optional),

        Expr::Try { expr, catch } => eval_try::<W, S>(expr, catch.as_deref(), value, optional),

        Expr::Error(msg) => eval_error::<W, S>(msg.as_deref(), value, optional),

        Expr::Builtin(builtin) => eval_builtin::<W, S>(builtin, value, optional),

        Expr::StringInterpolation(parts) => {
            eval_string_interpolation::<W, S>(parts, value, optional)
        }

        Expr::Format(format_type) => eval_format::<W>(format_type, value, optional),

        // Phase 8: Variables and Advanced Control Flow
        Expr::As { expr, var, body } => eval_as::<W, S>(expr, var, body, value, optional),
        Expr::Var(name) => {
            // Variable references without context should error
            // In practice, variables are resolved by eval_as which substitutes them
            QueryResult::Error(EvalError::new(format!("undefined variable: ${name}")))
        }
        Expr::Loc { line } => {
            // $__loc__ returns {"file": "<stdin>", "line": N}
            // where N is the 1-based line number in the jq filter source
            let mut obj = IndexMap::new();
            obj.insert("file".into(), OwnedValue::String("<stdin>".into()));
            obj.insert("line".into(), OwnedValue::Int(*line as i64));
            QueryResult::Owned(OwnedValue::Object(obj))
        }
        Expr::Env => {
            // $ENV returns an object containing all environment variables
            eval_env::<W>(optional)
        }
        Expr::Reduce {
            input,
            var,
            init,
            update,
        } => eval_reduce::<W, S>(input, var, init, update, value, optional),
        Expr::Foreach {
            input,
            var,
            init,
            update,
            extract,
        } => eval_foreach::<W, S>(
            input,
            var,
            init,
            update,
            extract.as_deref(),
            value,
            optional,
        ),
        Expr::Limit { n, expr } => eval_limit::<W, S>(n, expr, value, optional),
        Expr::FirstExpr(expr) => eval_first_expr::<W, S>(expr, value, optional),
        Expr::LastExpr(expr) => eval_last_expr::<W, S>(expr, value, optional),
        Expr::NthExpr { n, expr } => eval_nth_expr::<W, S>(n, expr, value, optional),
        Expr::Until { cond, update } => eval_until::<W, S>(cond, update, value, optional),
        Expr::While { cond, update } => eval_while::<W, S>(cond, update, value, optional),
        Expr::Repeat(expr) => eval_repeat::<W, S>(expr, value, optional),
        Expr::Range { from, to, step } => {
            eval_range::<W, S>(from, to.as_deref(), step.as_deref(), value, optional)
        }

        // Phase 9: Variables & Definitions
        Expr::AsPattern {
            expr,
            pattern,
            body,
        } => eval_as_pattern::<W, S>(expr, pattern, body, value, optional),
        Expr::FuncDef {
            name,
            params,
            body,
            then,
        } => eval_func_def::<W, S>(name, params, body, then, value, optional),
        Expr::FuncCall { name, args } => eval_func_call::<W>(name, args, value, optional),
        Expr::NamespacedCall {
            namespace,
            name,
            args: _,
        } => {
            // For now, namespaced calls return an error (modules not loaded)
            // This will be properly handled once module loading is implemented
            QueryResult::Error(EvalError::new(format!(
                "module '{namespace}' not loaded (namespaced call {namespace}::{name})"
            )))
        }

        // Assignment operators
        Expr::Assign { path, value: val } => eval_assign::<W, S>(path, val, value, optional),
        Expr::Update { path, filter } => eval_update::<W, S>(path, filter, value, optional),
        Expr::CompoundAssign {
            op,
            path,
            value: val,
        } => eval_compound_assign::<W, S>(*op, path, val, value, optional),
        Expr::AlternativeAssign { path, value: val } => {
            eval_alternative_assign::<W, S>(path, val, value, optional)
        }

        // Label-break for non-local control flow
        Expr::Label { name, body } => eval_label::<W, S>(name, body, value, optional),
        Expr::Break(name) => QueryResult::Break(name.clone()),
    }
}

/// Convert a literal to an owned value.
fn literal_to_owned(lit: &Literal) -> OwnedValue {
    match lit {
        Literal::Null => OwnedValue::Null,
        Literal::Bool(b) => OwnedValue::Bool(*b),
        Literal::Int(n) => OwnedValue::Int(*n),
        Literal::Float(f) => OwnedValue::Float(*f),
        Literal::String(s) => OwnedValue::String(s.clone()),
    }
}

/// Evaluate a comma expression (multiple outputs).
fn eval_comma<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    exprs: &[Expr],
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    if exprs.is_empty() {
        return QueryResult::None;
    }

    // Operands must reach the output in source order. While every operand so
    // far is borrowed from the document they accumulate in `borrowed` and
    // nothing is materialized — the fast path. The first owned operand promotes
    // that prefix into `owned` in place, and every later operand appends there,
    // so exactly one ordered accumulator is live at a time. Two parallel buckets
    // concatenated at the end lost each operand's position and hoisted every
    // borrowed one ahead of every owned one (#353). Same shape as the `Many` arm
    // of `eval_pipe` (#295).
    let mut borrowed: Vec<StandardJson<'a, W>> = Vec::new();
    let mut owned: Option<Vec<OwnedValue>> = None;

    for expr in exprs {
        match eval_single::<W, S>(expr, value.clone(), optional).materialize_cursor() {
            QueryResult::One(v) => match owned.as_mut() {
                Some(acc) => acc.push(to_owned(&v)),
                None => borrowed.push(v),
            },
            QueryResult::OneCursor(_) => {
                unreachable!("materialize_cursor should have converted this")
            }
            QueryResult::Many(vs) => match owned.as_mut() {
                Some(acc) => acc.extend(vs.iter().map(to_owned)),
                None => borrowed.extend(vs),
            },
            QueryResult::Owned(v) => owned
                .get_or_insert_with(|| {
                    core::mem::take(&mut borrowed)
                        .iter()
                        .map(to_owned)
                        .collect()
                })
                .push(v),
            QueryResult::ManyOwned(vs) => owned
                .get_or_insert_with(|| {
                    core::mem::take(&mut borrowed)
                        .iter()
                        .map(to_owned)
                        .collect()
                })
                .extend(vs),
            QueryResult::None => {}
            // A sibling that errors or breaks no longer discards the outputs
            // the earlier siblings already produced (#400): `(1,error("x"))`
            // now carries `1` forward as `Partial`'s prefix instead of
            // collapsing straight to a bare `Error`.
            QueryResult::Error(e) => {
                return partial(
                    merge_owned(borrowed, owned.unwrap_or_default()),
                    Control::Error(e),
                );
            }
            QueryResult::Break(label) => {
                return partial(
                    merge_owned(borrowed, owned.unwrap_or_default()),
                    Control::Break(label),
                );
            }
            QueryResult::Halt(code) => {
                return partial(
                    merge_owned(borrowed, owned.unwrap_or_default()),
                    Control::Halt(code),
                );
            }
            QueryResult::Partial(vs, control) => {
                let mut merged = merge_owned(borrowed, owned.unwrap_or_default());
                merged.extend(vs);
                return partial(merged, control);
            }
        }
    }

    match owned {
        Some(mut acc) if acc.len() == 1 => QueryResult::Owned(acc.pop().unwrap()),
        Some(acc) => QueryResult::ManyOwned(acc),
        None if borrowed.len() == 1 => QueryResult::One(borrowed.pop().unwrap()),
        None => QueryResult::Many(borrowed),
    }
}

/// Evaluate array construction.
fn eval_array_construction<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    inner: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // Collect all outputs from the inner expression into an array
    let result = eval_single::<W, S>(inner, value, optional);

    let items: Vec<OwnedValue> = match result.materialize_cursor() {
        QueryResult::One(v) => vec![to_owned(&v)],
        QueryResult::OneCursor(_) => unreachable!(),
        QueryResult::Many(vs) => vs.iter().map(to_owned).collect(),
        QueryResult::Owned(v) => vec![v],
        QueryResult::ManyOwned(vs) => vs,
        QueryResult::None => vec![],
        QueryResult::Error(e) => return QueryResult::Error(e),
        QueryResult::Break(label) => return QueryResult::Break(label),
        QueryResult::Halt(code) => return QueryResult::Halt(code),
        // Array construction is atomic in jq (verified: `[1,error("x"),3]`
        // produces no output at all, not a partial array) — a `Partial`
        // inner stream just surfaces its control, same as a bare one.
        QueryResult::Partial(_, Control::Error(e)) => return QueryResult::Error(e),
        QueryResult::Partial(_, Control::Break(label)) => return QueryResult::Break(label),
        QueryResult::Partial(_, Control::Halt(code)) => return QueryResult::Halt(code),
    };

    QueryResult::Owned(OwnedValue::Array(items))
}

/// Non-local exit out of the object-construction recursion.
///
/// `Error` and `Break` are the two `QueryResult` variants that must abandon the
/// product rather than contribute an output, so they travel as the `Err` side of
/// the recursive builder instead of being re-matched at every level. `None` is a
/// third: the `optional` flag (`?`) turns a non-string-key refusal into an empty
/// result instead of an error, the same way it does for `from_entries` and
/// `with_entries` — covered by `test_optional_suppresses_the_object_key_refusal`.
enum ObjectEscape {
    None,
    Error(EvalError),
    Break(String),
    Halt(i32),
}

/// Materialize every output of a sub-expression, plus a deferred escape if its
/// own generator terminates in an error or break.
///
/// jq doesn't stop early just because a generator is *going* to fail: `(1, 2,
/// error("x"))` still yields `1` and `2` before the error propagates, and
/// those outputs are real objects once combined with the rest of the entries
/// (`{a: 1, b: (2, error("x"))}` is `{"a":1,"b":2}` *then* the error — verified
/// against jq 1.7.1). So a `Partial` here is not an escape to peel off, the
/// way a bare `Error`/`Break` is (those two carry no outputs at all); its
/// prefix is exactly the outputs to combine, and its control is what fires
/// once that prefix is exhausted. [`QueryResult::collect_owned`] isn't reused
/// for the non-`Partial` cases because it would fold `Partial` down to just
/// its prefix and silently drop the control that must fire after it.
fn object_outputs<W: Clone + AsRef<[u64]>>(
    result: QueryResult<'_, W>,
) -> (Vec<OwnedValue>, Option<Control>) {
    match result {
        QueryResult::Error(e) => (Vec::new(), Some(Control::Error(e))),
        QueryResult::Break(label) => (Vec::new(), Some(Control::Break(label))),
        QueryResult::Halt(code) => (Vec::new(), Some(Control::Halt(code))),
        QueryResult::Partial(vs, control) => (vs, Some(control)),
        other => (other.collect_owned(), None),
    }
}

impl From<Control> for ObjectEscape {
    fn from(control: Control) -> Self {
        match control {
            Control::Error(e) => Self::Error(e),
            Control::Break(label) => Self::Break(label),
            Control::Halt(code) => Self::Halt(code),
        }
    }
}

/// Emit one object per combination of the remaining entries' key/value outputs.
///
/// Object construction is a generator in jq: an entry whose key or value yields
/// *n* outputs multiplies the objects produced (#354). The nesting below is what
/// gives jq's observable ordering and laziness:
///
/// - the *last* entry varies fastest, and within an entry the key varies slower
///   than the value — hence entries recurse and the key loop encloses the value
///   loop;
/// - `rest` is only reached from inside the value loop, so an entry with zero
///   outputs short-circuits every entry to its right without evaluating them
///   (`{a: empty, b: error("boom")}` is empty, not an error);
/// - the key's string-ness is checked at assembly time, after the value is in
///   hand, so `{(.n): empty}` with a numeric `.n` raises nothing and
///   `{(.n): error("VAL")}` reports `VAL` rather than the key-type error;
/// - a key or value generator's own deferred control (see [`object_outputs`])
///   is checked only after its whole prefix loop has run to completion, and
///   is then returned via `?` — which unwinds every enclosing loop immediately
///   rather than resuming them, matching jq's own all-or-nothing backtracking:
///   `{a: (1,2), b: (10,error("x"))}` is `{"a":1,"b":10}` then the error, never
///   `{"a":2,"b":10}` (jq 1.7.1).
///
/// `acc` is a push/pop stack rather than a map: the object is built once per
/// combination via `collect()`, which gives jq's duplicate-key rule (last value
/// wins, first position) for free from `IndexMap::insert`.
///
/// `sole` tracks whether every enclosing loop is running its one and only
/// iteration — i.e. whether the product is a single object, which is the case
/// for every query that predates #354. It exists purely so that case can move
/// the accumulated values into the object instead of cloning them, keeping the
/// common path allocation-for-allocation identical to the pre-#354 code. Without
/// it, `{a: .big}` would deep-clone `.big` on the way out.
fn build_object_entries<W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    entries: &[super::expr::ObjectEntry],
    value: &StandardJson<'_, W>,
    optional: bool,
    sole: bool,
    acc: &mut Vec<(String, OwnedValue)>,
    out: &mut Vec<OwnedValue>,
) -> Result<(), ObjectEscape> {
    let Some((entry, rest)) = entries.split_first() else {
        let object = if sole {
            // Only combination, so nothing will read `acc` again: every enclosing
            // loop is on its final iteration, and the `acc.pop()` each one runs on
            // the way out is a no-op on the emptied vector.
            core::mem::take(acc).into_iter().collect::<IndexMap<_, _>>()
        } else {
            acc.iter().cloned().collect::<IndexMap<_, _>>()
        };
        out.push(OwnedValue::Object(object));
        return Ok(());
    };

    let (keys, key_trailing) = match &entry.key {
        ObjectKey::Literal(s) => (vec![OwnedValue::String(s.clone())], None),
        ObjectKey::Expr(key_expr) => {
            object_outputs(eval_single::<W, S>(key_expr, value.clone(), optional))
        }
    };
    let sole = sole && keys.len() == 1;

    for key in keys {
        let (vals, val_trailing) =
            object_outputs(eval_single::<W, S>(&entry.value, value.clone(), optional));
        let sole = sole && vals.len() == 1;

        for val in vals {
            let OwnedValue::String(key_str) = &key else {
                // A single non-string key is jq's `Cannot use <t> (<v>) as
                // object key` — the same sentence `from_entries` raises,
                // because jq *defines* `from_entries` as object construction
                // over the entries (#391) — unless `optional` (`?`) is set, in
                // which case it is suppressed into an empty result instead.
                return Err(if optional {
                    ObjectEscape::None
                } else {
                    ObjectEscape::Error(EvalError::cannot_use_as_object_key(&key))
                });
            };

            acc.push((key_str.clone(), val));
            let result = build_object_entries::<W, S>(rest, value, optional, sole, acc, out);
            acc.pop();
            result?;
        }

        // The value generator's own prefix is exhausted — now its deferred
        // control fires, aborting every enclosing loop via `?` (never trying
        // this entry's next key, nor an earlier entry's next value).
        if let Some(control) = val_trailing {
            return Err(control.into());
        }
    }

    // Same deferred-control shape as above, one level up: only once every key
    // this generator produced has had its value loop run to completion.
    if let Some(control) = key_trailing {
        return Err(control.into());
    }

    Ok(())
}

/// Evaluate object construction.
fn eval_object_construction<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    entries: &[super::expr::ObjectEntry],
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    let mut objects = Vec::new();
    let mut acc = Vec::new();

    // jq streams, so it emits the combinations produced before an error and
    // only then fails: `try {("a",1):2}` is `{"a":2}` there, and here — the
    // objects already pushed to `out` by the time `build_object_entries`
    // returns `Err` travel onward as `QueryResult::Partial`'s prefix, the same
    // carrier `eval_comma` uses for `(1,error("x"))` (#400/#494).
    match build_object_entries::<W, S>(entries, &value, optional, true, &mut acc, &mut objects) {
        Ok(()) => {}
        Err(ObjectEscape::None) => return QueryResult::None,
        Err(ObjectEscape::Break(label)) => {
            return if objects.is_empty() {
                QueryResult::Break(label)
            } else {
                QueryResult::Partial(objects, Control::Break(label))
            };
        }
        Err(ObjectEscape::Halt(code)) => {
            return if objects.is_empty() {
                QueryResult::Halt(code)
            } else {
                QueryResult::Partial(objects, Control::Halt(code))
            };
        }
        Err(ObjectEscape::Error(e)) => {
            return if objects.is_empty() {
                QueryResult::Error(e)
            } else {
                QueryResult::Partial(objects, Control::Error(e))
            };
        }
    }

    if objects.is_empty() {
        QueryResult::None
    } else if objects.len() == 1 {
        QueryResult::Owned(objects.pop().unwrap())
    } else {
        QueryResult::ManyOwned(objects)
    }
}

/// Evaluate recursive descent.
fn eval_recursive_descent<W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    value: StandardJson<'_, W>,
) -> QueryResult<'_, W> {
    let mut results = Vec::new();
    collect_recursive::<W, S>(&value, &mut results);
    QueryResult::Many(results)
}

/// Collect all values recursively.
fn collect_recursive<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    value: &StandardJson<'a, W>,
    results: &mut Vec<StandardJson<'a, W>>,
) {
    results.push(value.clone());

    match value {
        StandardJson::Array(elements) => {
            for elem in *elements {
                collect_recursive::<W, S>(&elem, results);
            }
        }
        StandardJson::Object(fields) => {
            for field in *fields {
                collect_recursive::<W, S>(&field.value(), results);
            }
        }
        _ => {}
    }
}

/// Merge a borrowed accumulator and an owned accumulator into one owned
/// prefix, in the order their values were produced. Shared by every
/// stream-combining function that promotes a borrowed `Vec<StandardJson>` to
/// owned the moment an owned value (or a terminal control) forces it.
fn merge_owned<W: Clone + AsRef<[u64]>>(
    borrowed: Vec<StandardJson<'_, W>>,
    owned: Vec<OwnedValue>,
) -> Vec<OwnedValue> {
    let mut merged: Vec<OwnedValue> = borrowed.iter().map(to_owned).collect();
    merged.extend(owned);
    merged
}

/// Normalize a `Vec<OwnedValue>` accumulator into the smallest `QueryResult`
/// shape that represents it: empty stays `None`, one value collapses to
/// `Owned`, more than one stays `ManyOwned`.
fn owned_vec_to_result<'a, W>(mut vs: Vec<OwnedValue>) -> QueryResult<'a, W> {
    match vs.len() {
        0 => QueryResult::None,
        1 => QueryResult::Owned(vs.pop().unwrap()),
        _ => QueryResult::ManyOwned(vs),
    }
}

/// Normalize a prefix and its terminator into a `QueryResult` (#400, #494).
///
/// An empty prefix collapses to the bare `Error`/`Break`/`Halt` variant, so
/// callers that had nothing accumulated before hitting a control signal
/// produce exactly what they did before `Partial` existed.
fn partial<'a, W>(prefix: Vec<OwnedValue>, control: Control) -> QueryResult<'a, W> {
    if prefix.is_empty() {
        match control {
            Control::Error(e) => QueryResult::Error(e),
            Control::Break(label) => QueryResult::Break(label),
            Control::Halt(code) => QueryResult::Halt(code),
        }
    } else {
        QueryResult::Partial(prefix, control)
    }
}

/// Evaluate `expr` against an owned `input`, returning every output it
/// produces instead of collapsing them, plus any terminating `Control`
/// (#534). Thin wrapper over [`eval_owned_input`], which already keeps
/// `Many`/`ManyOwned`/`Partial` intact instead of folding — this just
/// unpacks its `QueryResult` into the `(outputs, trailing control)` shape
/// `reduce`/`foreach`/`while`/`until` build their fold/fork logic on top of.
fn eval_owned_expr_fork<S: EvalSemantics>(
    expr: &Expr,
    input: &OwnedValue,
    optional: bool,
) -> (Vec<OwnedValue>, Option<Control>) {
    match eval_owned_input::<Vec<u64>, S>(expr, input, optional) {
        QueryResult::Owned(v) => (vec![v], None),
        QueryResult::ManyOwned(vs) => (vs, None),
        QueryResult::None => (Vec::new(), None),
        QueryResult::Error(e) => (Vec::new(), Some(Control::Error(e))),
        QueryResult::Break(label) => (Vec::new(), Some(Control::Break(label))),
        QueryResult::Halt(code) => (Vec::new(), Some(Control::Halt(code))),
        QueryResult::Partial(vs, control) => (vs, Some(control)),
        QueryResult::One(_) | QueryResult::OneCursor(_) | QueryResult::Many(_) => {
            unreachable!(
                "eval_owned_input always normalizes to Owned/ManyOwned/None/Error/Break/Halt/Partial"
            )
        }
    }
}

/// Finalize a fork/fold construct's accumulated `outputs`, given an optional
/// terminating `Control` (#534). Mirrors `partial()`'s "outputs already
/// produced don't vanish" contract (#400, #494): an optional context keeps
/// a construct's own legitimate prior output and only silences a trailing
/// `Error`, it does not discard everything.
///
/// A `Break` always propagates via `partial` here, uncaught by `optional` —
/// deliberately: `label $out | (1, (reduce (1,2) as $x (0; break $out))?,
/// 4)` gives jq's `1`, `4` (its `?` does swallow an escaping `break` whose
/// matching `label` sits outside it), and this codebase now matches that
/// too (#693), but the catch happens one level up, at the `?`/`try`
/// boundary wrapping whichever fork construct raised the `Break` —
/// `eval_try`/`Expr::Optional`'s dispatch, not here. This function only
/// ever sees `optional` after that boundary has already had its chance to
/// react, so it correctly leaves `Break` alone and only ever silences a
/// trailing `Error`.
fn finish_fork<'a, W>(
    outputs: Vec<OwnedValue>,
    control: Option<Control>,
    optional: bool,
) -> QueryResult<'a, W> {
    match control {
        None => owned_vec_to_result(outputs),
        Some(Control::Error(_)) if optional => owned_vec_to_result(outputs),
        Some(control) => partial(outputs, control),
    }
}

/// Splice `prefix` in front of whatever `result` yields.
///
/// Used by `try`/`catch` (#400): the body's outputs before the error, then
/// the catch handler's own result — which may itself be `Partial` if the
/// handler errors too, in which case the two prefixes concatenate.
fn prepend<W: Clone + AsRef<[u64]>>(
    mut prefix: Vec<OwnedValue>,
    result: QueryResult<'_, W>,
) -> QueryResult<'_, W> {
    if prefix.is_empty() {
        return result;
    }
    match result.materialize_cursor() {
        QueryResult::None => owned_vec_to_result(prefix),
        QueryResult::OneCursor(_) => unreachable!("materialize_cursor removes OneCursor"),
        QueryResult::One(v) => {
            prefix.push(to_owned(&v));
            owned_vec_to_result(prefix)
        }
        QueryResult::Owned(v) => {
            prefix.push(v);
            owned_vec_to_result(prefix)
        }
        QueryResult::Many(vs) => {
            prefix.extend(vs.iter().map(to_owned));
            owned_vec_to_result(prefix)
        }
        QueryResult::ManyOwned(vs) => {
            prefix.extend(vs);
            owned_vec_to_result(prefix)
        }
        QueryResult::Error(e) => partial(prefix, Control::Error(e)),
        QueryResult::Break(label) => partial(prefix, Control::Break(label)),
        QueryResult::Halt(code) => partial(prefix, Control::Halt(code)),
        QueryResult::Partial(vs, control) => {
            prefix.extend(vs);
            partial(prefix, control)
        }
    }
}

/// Convert a QueryResult to an OwnedValue for use in computations.
fn result_to_owned<W: Clone + AsRef<[u64]>>(
    result: QueryResult<'_, W>,
) -> Result<OwnedValue, EvalEscape> {
    match result.materialize_cursor() {
        QueryResult::One(v) => Ok(to_owned(&v)),
        QueryResult::OneCursor(_) => unreachable!(),
        QueryResult::Owned(v) => Ok(v),
        QueryResult::Many(vs) => {
            if let Some(v) = vs.first() {
                Ok(to_owned(v))
            } else {
                Err(EvalError::new("empty result").into())
            }
        }
        QueryResult::ManyOwned(vs) => {
            if let Some(v) = vs.into_iter().next() {
                Ok(v)
            } else {
                Err(EvalError::new("empty result").into())
            }
        }
        // Same "take the first output, ignore the rest" policy already
        // applied to `Many`/`ManyOwned` above — a `Partial` prefix is never
        // empty (see `partial`), so there is always a first value to take.
        //
        // A `Partial`'s trailing `Halt` still wins over the prefix, though:
        // an argument stream that produced values and *then* halted must
        // halt, not quietly compute with the first value (#791).
        QueryResult::Partial(_, Control::Halt(code)) => Err(EvalEscape::Halt(code)),
        QueryResult::Partial(vs, _control) => Ok(vs.into_iter().next().unwrap()),
        QueryResult::None => Err(EvalError::new("no value").into()),
        QueryResult::Error(e) => Err(e.into()),
        QueryResult::Break(label) => {
            Err(EvalError::new(format!("break ${label} not in label")).into())
        }
        // An operand-context halt (`1 + halt`) travels as its own
        // `EvalEscape` variant, so no consumer can mistake it for a
        // catchable error (#791): `try`/`catch` and `?` handle only
        // `EvalEscape::Error`, and the `From` conversions to
        // `QueryResult`/`Control` preserve `Halt` by construction.
        QueryResult::Halt(code) => Err(EvalEscape::Halt(code)),
    }
}

/// Keep only the truthy outputs of a stream, normalizing the result.
///
/// A stream with no surviving output becomes [`QueryResult::None`], and a
/// single survivor is normalized to `One`/`Owned` so the caller cannot tell a
/// filtered stream from a value that was single all along. `None`, `Error` and
/// `Break` pass through untouched — filtering says nothing about them.
///
/// Borrowed values stay borrowed: this never calls [`to_owned`], so `//` over a
/// document-derived stream keeps the zero-copy path.
fn retain_truthy<W: Clone + AsRef<[u64]>>(result: QueryResult<'_, W>) -> QueryResult<'_, W> {
    match result.materialize_cursor() {
        QueryResult::One(v) => {
            if json_is_truthy(&v) {
                QueryResult::One(v)
            } else {
                QueryResult::None
            }
        }
        QueryResult::OneCursor(_) => unreachable!("materialize_cursor removes OneCursor"),
        QueryResult::Owned(v) => {
            if v.is_truthy() {
                QueryResult::Owned(v)
            } else {
                QueryResult::None
            }
        }
        QueryResult::Many(mut vs) => {
            vs.retain(json_is_truthy);
            match vs.len() {
                0 => QueryResult::None,
                1 => QueryResult::One(vs.pop().unwrap()),
                _ => QueryResult::Many(vs),
            }
        }
        QueryResult::ManyOwned(mut vs) => {
            vs.retain(OwnedValue::is_truthy);
            match vs.len() {
                0 => QueryResult::None,
                1 => QueryResult::Owned(vs.pop().unwrap()),
                _ => QueryResult::ManyOwned(vs),
            }
        }
        // The prefix is filtered exactly like `ManyOwned` above — jq's `//`
        // retains truthy outputs regardless of whether the stream that
        // produced them went on to error (#400): `(1,false,error("x")) // 2`
        // is `1`, not `1 false`, then the error.
        QueryResult::Partial(mut vs, control) => {
            vs.retain(OwnedValue::is_truthy);
            partial(vs, control)
        }
        other @ (QueryResult::None
        | QueryResult::Error(_)
        | QueryResult::Break(_)
        | QueryResult::Halt(_)) => other,
    }
}

/// Append one truthiness bit per output of a stream to `out`.
///
/// Returns `Some(control)` when the stream was an `Error`, a `Break`, or a
/// `Partial` (in which case the `Partial`'s own prefix is pushed first), which
/// the caller must combine with whatever it has already accumulated in `out`
/// and propagate as a `Partial` of its own (#400) — `out` itself is *not*
/// discarded here, unlike before #400/#494; the caller owns it and decides
/// how to fold it into the final result. `None` when every output was
/// consumed. An empty stream contributes no bits, which is how `empty and true`
/// ends up yielding nothing.
///
/// Collecting `bool` rather than `OwnedValue` is deliberate: `and`/`or` only
/// ever need whether an output was truthy, never the output itself.
fn push_truthiness<W: Clone + AsRef<[u64]>>(
    result: QueryResult<'_, W>,
    out: &mut Vec<bool>,
) -> Option<Control> {
    match result.materialize_cursor() {
        QueryResult::One(v) => out.push(json_is_truthy(&v)),
        QueryResult::OneCursor(_) => unreachable!("materialize_cursor removes OneCursor"),
        QueryResult::Owned(v) => out.push(v.is_truthy()),
        QueryResult::Many(vs) => out.extend(vs.iter().map(json_is_truthy)),
        QueryResult::ManyOwned(vs) => out.extend(vs.iter().map(OwnedValue::is_truthy)),
        QueryResult::None => {}
        QueryResult::Error(e) => return Some(Control::Error(e)),
        QueryResult::Break(label) => return Some(Control::Break(label)),
        QueryResult::Halt(code) => return Some(Control::Halt(code)),
        QueryResult::Partial(vs, control) => {
            out.extend(vs.iter().map(OwnedValue::is_truthy));
            return Some(control);
        }
    }
    None
}

/// Turn a stream of booleans into the result of a boolean operator.
fn bools_to_result<'a, W: Clone + AsRef<[u64]>>(mut bools: Vec<bool>) -> QueryResult<'a, W> {
    match bools.len() {
        0 => QueryResult::None,
        1 => QueryResult::Owned(OwnedValue::Bool(bools.pop().unwrap())),
        _ => QueryResult::ManyOwned(bools.into_iter().map(OwnedValue::Bool).collect()),
    }
}

/// The `OwnedValue`-collecting analog of [`push_truthiness`]: pushes every
/// output `result` produced into `out`, returning any terminating `Control`
/// instead of collapsing to the first output the way [`result_to_owned`]
/// does. Used by [`eval_binary_fanout`] (#768) to fork an arithmetic/
/// comparison operand into all of its outputs, mirroring how `push_truthiness`
/// already forks `and`/`or`'s operands.
fn push_owned_values<W: Clone + AsRef<[u64]>>(
    result: QueryResult<'_, W>,
    out: &mut Vec<OwnedValue>,
) -> Option<Control> {
    match result.materialize_cursor() {
        QueryResult::One(v) => out.push(to_owned(&v)),
        QueryResult::OneCursor(_) => unreachable!("materialize_cursor removes OneCursor"),
        QueryResult::Owned(v) => out.push(v),
        QueryResult::Many(vs) => out.extend(vs.iter().map(to_owned)),
        QueryResult::ManyOwned(vs) => out.extend(vs),
        QueryResult::None => {}
        QueryResult::Error(e) => return Some(Control::Error(e)),
        QueryResult::Break(label) => return Some(Control::Break(label)),
        QueryResult::Halt(code) => return Some(Control::Halt(code)),
        QueryResult::Partial(vs, control) => {
            out.extend(vs);
            return Some(control);
        }
    }
    None
}

/// Evaluate `body(bit)` once per truthy-bit of a condition stream, merging
/// the results in order. Shared by `eval_if` and `builtin_select` so a
/// multi-output condition (`if (true,false) then "a" else "b" end` /
/// `select((false,false) and true)`) fans out the same way both call it,
/// instead of only consulting the condition's first output (#378).
///
/// Same borrowed/owned promotion as `eval_comma` (#353): outputs stay
/// borrowed until an owned/computed body result forces the accumulator to
/// promote, and a sibling that errors or breaks keeps whatever was already
/// produced as a `Partial` prefix (#400) rather than discarding it.
fn eval_fanout<'a, W: Clone + AsRef<[u64]>>(
    cond_result: QueryResult<'a, W>,
    mut body: impl FnMut(bool) -> QueryResult<'a, W>,
) -> QueryResult<'a, W> {
    let mut bits = Vec::new();
    let cond_control = push_truthiness(cond_result, &mut bits);

    let mut borrowed: Vec<StandardJson<'a, W>> = Vec::new();
    let mut owned: Option<Vec<OwnedValue>> = None;

    for bit in bits {
        match body(bit).materialize_cursor() {
            QueryResult::One(v) => match owned.as_mut() {
                Some(acc) => acc.push(to_owned(&v)),
                None => borrowed.push(v),
            },
            QueryResult::OneCursor(_) => {
                unreachable!("materialize_cursor should have converted this")
            }
            QueryResult::Many(vs) => match owned.as_mut() {
                Some(acc) => acc.extend(vs.iter().map(to_owned)),
                None => borrowed.extend(vs),
            },
            QueryResult::Owned(v) => owned
                .get_or_insert_with(|| {
                    core::mem::take(&mut borrowed)
                        .iter()
                        .map(to_owned)
                        .collect()
                })
                .push(v),
            QueryResult::ManyOwned(vs) => owned
                .get_or_insert_with(|| {
                    core::mem::take(&mut borrowed)
                        .iter()
                        .map(to_owned)
                        .collect()
                })
                .extend(vs),
            QueryResult::None => {}
            QueryResult::Error(e) => {
                return partial(
                    merge_owned(borrowed, owned.unwrap_or_default()),
                    Control::Error(e),
                );
            }
            QueryResult::Break(label) => {
                return partial(
                    merge_owned(borrowed, owned.unwrap_or_default()),
                    Control::Break(label),
                );
            }
            QueryResult::Halt(code) => {
                return partial(
                    merge_owned(borrowed, owned.unwrap_or_default()),
                    Control::Halt(code),
                );
            }
            QueryResult::Partial(vs, control) => {
                let mut merged = merge_owned(borrowed, owned.unwrap_or_default());
                merged.extend(vs);
                return partial(merged, control);
            }
        }
    }

    match cond_control {
        Some(control) => partial(merge_owned(borrowed, owned.unwrap_or_default()), control),
        None => match owned {
            Some(mut acc) if acc.len() == 1 => QueryResult::Owned(acc.pop().unwrap()),
            Some(acc) => QueryResult::ManyOwned(acc),
            None if borrowed.len() == 1 => QueryResult::One(borrowed.pop().unwrap()),
            None => QueryResult::Many(borrowed),
        },
    }
}

/// Evaluate `left op right` over every pairing jq's cartesian fanout
/// produces, right operand outer / left operand inner (#768): `(1,2) + (10,20)`
/// is `11,12,21,22` (right=10 held fixed while left runs 1,2; then right=20).
/// Shared by [`eval_arithmetic`] and [`eval_compare`], which differ only in
/// how they combine one pairing — the fallible `combine` closure — since
/// both used to fork through [`result_to_owned`], which collapses a
/// multi-output operand to its first value (correct for `result_to_owned`'s
/// other single-value callers, wrong here).
///
/// This is the opposite nesting from `and`/`or` ([`eval_boolean`],
/// left-outer/right-inner: short-circuiting needs left's value first). Its
/// structure otherwise mirrors `eval_boolean`'s: fork one operand via a
/// `push_*`-style helper into outputs plus a trailing `Control`, loop over
/// it, fork the other operand per iteration.
///
/// A `combine` error (op-application failure, e.g. `"a" + 1`) always aborts
/// the whole fanout rather than skipping just that pairing — jq doesn't
/// retry a generator past a fatal error — via [`finish_fork`], which also
/// reproduces the original single-pairing `Err(_) if optional => None`
/// policy exactly when there is no fanout. An operand-evaluation error/break
/// is never gated by `optional` here (matching the original's unconditional
/// propagation, and `eval_boolean`'s own precedent) — an enclosing `?`/`try`
/// is what catches it, one level up.
/// Shared right-outer/left-inner fanout core behind [`eval_binary_fanout`]
/// and `eval_binary_fanout_with_path_context`.
///
/// The two callers differ only in *how* an operand expression is evaluated
/// (plain value evaluation vs. path-context-tracking evaluation) — the
/// fanout/fork/`Partial`-propagation logic itself (this function's body) was
/// duplicated verbatim between them until now, which is exactly how it
/// happened that a collapse-to-first-value bug fixed here for #768 was
/// independently re-acquired by the path-context copy and had to be fixed
/// again for #822: two definitions of the same algorithm can drift, one
/// does not. `eval_operand` closes over whichever evaluator its caller
/// wants; everything downstream of an operand's `QueryResult` is unchanged.
fn binary_fanout_core<'a, W: Clone + AsRef<[u64]>>(
    mut eval_operand: impl FnMut(&Expr) -> QueryResult<'a, W>,
    left: &Expr,
    right: &Expr,
    optional: bool,
    mut combine: impl FnMut(OwnedValue, OwnedValue) -> Result<OwnedValue, EvalError>,
) -> QueryResult<'a, W> {
    let mut right_vals = Vec::new();
    let right_control = push_owned_values(eval_operand(right), &mut right_vals);

    let mut out: Vec<OwnedValue> = Vec::new();
    for right_val in &right_vals {
        let mut left_vals = Vec::new();
        let left_control = push_owned_values(eval_operand(left), &mut left_vals);

        for left_val in left_vals {
            match combine(left_val, right_val.clone()) {
                Ok(v) => out.push(v),
                Err(e) => return finish_fork(out, Some(e.into()), optional),
            }
        }

        if let Some(control) = left_control {
            return partial(out, control);
        }
    }

    match right_control {
        Some(control) => partial(out, control),
        None => owned_vec_to_result(out),
    }
}

fn eval_binary_fanout<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    left: &Expr,
    right: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
    combine: impl FnMut(OwnedValue, OwnedValue) -> Result<OwnedValue, EvalError>,
) -> QueryResult<'a, W> {
    binary_fanout_core(
        move |expr| eval_single::<W, S>(expr, value.clone(), optional),
        left,
        right,
        optional,
        combine,
    )
}

/// Evaluate arithmetic operations.
fn eval_arithmetic<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    op: ArithOp,
    left: &Expr,
    right: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    eval_binary_fanout::<W, S>(
        left,
        right,
        value,
        optional,
        |left_val, right_val| match op {
            ArithOp::Add => arith_add::<S>(left_val, right_val),
            ArithOp::Sub => arith_sub::<S>(left_val, right_val),
            ArithOp::Mul(flags) => arith_mul::<S>(left_val, right_val, flags),
            ArithOp::Div => arith_div::<S>(left_val, right_val),
            ArithOp::Mod => arith_mod::<S>(left_val, right_val),
        },
    )
}

/// Add two values (numbers, strings, arrays, objects).
fn arith_add<S: EvalSemantics>(
    left: OwnedValue,
    right: OwnedValue,
) -> Result<OwnedValue, EvalError> {
    // A `NumberLiteral` operand degrades to plain `Int`/`Float` the moment it
    // computes with something -- jq gives computed numbers canonical
    // formatting, only values that reach output untouched keep their literal.
    let (left, right) = (left.into_plain_number(), right.into_plain_number());
    match (left, right) {
        // Number addition - jq converts to float on overflow, yq wraps
        (OwnedValue::Int(a), OwnedValue::Int(b)) => {
            if S::OVERFLOW_WRAPS {
                // yq behavior: wrapping add
                Ok(OwnedValue::Int(a.wrapping_add(b)))
            } else {
                // jq behavior: convert to float on overflow
                match a.checked_add(b) {
                    Some(result) => Ok(OwnedValue::Int(result)),
                    None => Ok(OwnedValue::Float(a as f64 + b as f64)),
                }
            }
        }
        (OwnedValue::Int(a), OwnedValue::Float(b)) => Ok(OwnedValue::Float(a as f64 + b)),
        (OwnedValue::Float(a), OwnedValue::Int(b)) => Ok(OwnedValue::Float(a + b as f64)),
        (OwnedValue::Float(a), OwnedValue::Float(b)) => Ok(OwnedValue::Float(a + b)),
        // String concatenation
        (OwnedValue::String(mut a), OwnedValue::String(b)) => {
            a.push_str(&b);
            Ok(OwnedValue::String(a))
        }
        // Array concatenation
        (OwnedValue::Array(mut a), OwnedValue::Array(b)) => {
            a.extend(b);
            Ok(OwnedValue::Array(a))
        }
        // Object merge (right overwrites left)
        (OwnedValue::Object(mut a), OwnedValue::Object(b)) => {
            a.extend(b);
            Ok(OwnedValue::Object(a))
        }
        // null + x = x, x + null = x
        (OwnedValue::Null, other) | (other, OwnedValue::Null) => Ok(other),
        (a, b) => Err(EvalError::binary_op(&a, &b, BinOp::Add)),
    }
}

/// Subtract two values.
fn arith_sub<S: EvalSemantics>(
    left: OwnedValue,
    right: OwnedValue,
) -> Result<OwnedValue, EvalError> {
    let (left, right) = (left.into_plain_number(), right.into_plain_number());
    match (left, right) {
        // jq converts to float on overflow, yq wraps
        (OwnedValue::Int(a), OwnedValue::Int(b)) => {
            if S::OVERFLOW_WRAPS {
                // yq behavior: wrapping sub
                Ok(OwnedValue::Int(a.wrapping_sub(b)))
            } else {
                // jq behavior: convert to float on overflow
                match a.checked_sub(b) {
                    Some(result) => Ok(OwnedValue::Int(result)),
                    None => Ok(OwnedValue::Float(a as f64 - b as f64)),
                }
            }
        }
        (OwnedValue::Int(a), OwnedValue::Float(b)) => Ok(OwnedValue::Float(a as f64 - b)),
        (OwnedValue::Float(a), OwnedValue::Int(b)) => Ok(OwnedValue::Float(a - b as f64)),
        (OwnedValue::Float(a), OwnedValue::Float(b)) => Ok(OwnedValue::Float(a - b)),
        // Array subtraction (remove elements)
        (OwnedValue::Array(a), OwnedValue::Array(b)) => {
            let result: Vec<_> = a.into_iter().filter(|x| !b.contains(x)).collect();
            Ok(OwnedValue::Array(result))
        }
        (a, b) => Err(EvalError::binary_op(&a, &b, BinOp::Subtract)),
    }
}

/// Multiply two values.
fn arith_mul<S: EvalSemantics>(
    left: OwnedValue,
    right: OwnedValue,
    flags: MergeFlags,
) -> Result<OwnedValue, EvalError> {
    let (left, right) = (left.into_plain_number(), right.into_plain_number());
    match (left, right) {
        // jq converts to float on overflow, yq wraps
        (OwnedValue::Int(a), OwnedValue::Int(b)) => {
            if S::OVERFLOW_WRAPS {
                // yq behavior: wrapping mul
                Ok(OwnedValue::Int(a.wrapping_mul(b)))
            } else {
                // jq behavior: convert to float on overflow
                match a.checked_mul(b) {
                    Some(result) => Ok(OwnedValue::Int(result)),
                    None => Ok(OwnedValue::Float(a as f64 * b as f64)),
                }
            }
        }
        (OwnedValue::Int(a), OwnedValue::Float(b)) => Ok(OwnedValue::Float(a as f64 * b)),
        (OwnedValue::Float(a), OwnedValue::Int(b)) => Ok(OwnedValue::Float(a * b as f64)),
        (OwnedValue::Float(a), OwnedValue::Float(b)) => Ok(OwnedValue::Float(a * b)),
        // String repetition: "ab" * 3 = "ababab". jq >= 1.7 yields "" for
        // n == 0 and null only for n < 0 (jqlang/jq#1593)
        (OwnedValue::String(s), OwnedValue::Int(n))
        | (OwnedValue::Int(n), OwnedValue::String(s)) => {
            if n < 0 {
                Ok(OwnedValue::Null)
            } else {
                Ok(OwnedValue::String(s.repeat(n as usize)))
            }
        }
        // Object recursive merge (yq's `*`/`*=` merge operator; also jq's
        // plain object multiply, which has always done the same thing).
        // Uses merge_existing (not merge_values) because `a`/`b` are the
        // direct `.path *= value` assignment target: `a` already "exists"
        // as a concrete value, so `n`-gating must consider it (see
        // merge_existing) — unlike the null-derived-empty-container arms
        // below, which merge_values still handles unconditionally.
        (a @ OwnedValue::Object(_), b @ OwnedValue::Object(_)) => Ok(merge_existing(a, b, flags)),
        // Array merge is yq-only: real jq has no array-merge concept and
        // errors here too (falls through to the generic error arm below).
        // Unflagged: rhs replaces lhs wholesale. `+`/`d` flags change that
        // (see merge_values) — flags are unreachable in jq-mode ASTs, so
        // this arm and its flag handling only ever fire for yq.
        (a @ OwnedValue::Array(_), b @ OwnedValue::Array(_)) if S::ARRAY_MULTIPLY_MERGES => {
            Ok(merge_existing(a, b, flags))
        }
        // yq: null is an empty container for merge purposes. A null right
        // operand is a no-op regardless of flags (real yq: `x *= null`
        // leaves `x` untouched, whatever `x` is). A null left operand
        // merging with an object/array merges as if it started from
        // `{}`/`[]`, routing through the same merge_values() call as a real
        // container pair — so `?`/`n` gating (which only takes effect once
        // merge_values recurses into positions) behaves exactly as if the
        // target already existed as an empty container. This is what makes
        // the merge-flag suffixes (#713) work on a top-level target that's
        // `null` or entirely absent (`.a` on a missing key evaluates to
        // `null`), not just on nested fields within an existing container.
        (left, OwnedValue::Null) if S::NULL_MERGES_AS_EMPTY => Ok(left),
        (OwnedValue::Null, b @ OwnedValue::Object(_)) if S::NULL_MERGES_AS_EMPTY => {
            Ok(merge_values(OwnedValue::Object(IndexMap::new()), b, flags))
        }
        (OwnedValue::Null, b @ OwnedValue::Array(_)) if S::NULL_MERGES_AS_EMPTY => {
            Ok(merge_values(OwnedValue::Array(Vec::new()), b, flags))
        }
        // null * x = null
        (OwnedValue::Null, _) | (_, OwnedValue::Null) => Ok(OwnedValue::Null),
        (a, b) => Err(EvalError::binary_op(&a, &b, BinOp::Multiply)),
    }
}

/// Merge two values for `*`/`*=` where `right` merges into a position
/// synthesized to stand in for an absent/null `left` (the
/// `NULL_MERGES_AS_EMPTY` arms of `arith_mul`) — so unlike [`merge_existing`],
/// there is no real prior value to gate `n` against. Matching containers
/// (`Object`+`Object`, or `Array`+`Array` under `d` without `+`) merge
/// structurally, recursing into positions gated individually by
/// [`merge_position`]; anything else is a plain leaf replace.
fn merge_values(left: OwnedValue, right: OwnedValue, flags: MergeFlags) -> OwnedValue {
    match (left, right) {
        (OwnedValue::Object(a), OwnedValue::Object(b)) => {
            OwnedValue::Object(merge_object_fields(a, b, flags))
        }
        (OwnedValue::Array(a), OwnedValue::Array(b))
            if flags.deep_merge_arrays && !flags.append_arrays =>
        {
            OwnedValue::Array(merge_arrays_by_index(a, b, flags))
        }
        (existing, incoming) => merge_leaf(existing, incoming, flags),
    }
}

/// The terminal case of a merge: `existing` and `incoming` are not a
/// matching container pair we'd recurse into, so decide the value outright.
/// `+` makes two arrays concatenate; everything else is a plain replace
/// (`incoming` wins) — this is also yq's default for unflagged arrays.
fn merge_leaf(existing: OwnedValue, incoming: OwnedValue, flags: MergeFlags) -> OwnedValue {
    match (existing, incoming) {
        (OwnedValue::Array(mut a), OwnedValue::Array(b)) if flags.append_arrays => {
            a.extend(b);
            OwnedValue::Array(a)
        }
        (_, incoming) => incoming,
    }
}

/// Merge `incoming` into a position known to already hold `existing` —
/// shared by [`merge_position`] (a nested field/index reached via
/// recursion) and `arith_mul`'s top-level `Object`/`Array` arms (the direct
/// `.path *= value` assignment target, which already "exists" as a concrete
/// value once the `NULL_MERGES_AS_EMPTY` absent/null case has been ruled
/// out). A matching container pair always recurses structurally regardless
/// of `?`/`n` — those flags only gate genuine leaf writes, not whether an
/// existing nested container gets walked. This is what makes `n`/`?`
/// propagate correctly through nested merges: a parent key that already
/// exists still gets recursed into, so *its* new children can be added (or
/// blocked) individually.
fn merge_existing(existing: OwnedValue, incoming: OwnedValue, flags: MergeFlags) -> OwnedValue {
    match (existing, incoming) {
        (OwnedValue::Object(a), OwnedValue::Object(b)) => {
            OwnedValue::Object(merge_object_fields(a, b, flags))
        }
        (OwnedValue::Array(a), OwnedValue::Array(b))
            if flags.deep_merge_arrays && !flags.append_arrays =>
        {
            OwnedValue::Array(merge_arrays_by_index(a, b, flags))
        }
        (existing, incoming) => {
            // `n`: only write if the existing value is already null. `?`
            // never blocks here — it only blocks brand-new positions, and
            // `existing` is already known to be present.
            if flags.only_new && !matches!(existing, OwnedValue::Null) {
                existing
            } else {
                merge_leaf(existing, incoming, flags)
            }
        }
    }
}

/// Decide the merged value for one position (an object field or array
/// index) of a `*`/`*=` merge, honoring `?`/`n` gating. `existing` is
/// `None` when the position isn't present in `left` yet. Returns `None` to
/// mean "leave `left` unchanged here" (blocked by `?`), `Some(v)` to mean
/// "set it to `v`".
///
/// `only_existing_applies` scopes `?` to object fields: real yq's `?` never
/// blocks creating a brand-new *array* index, only a brand-new *object*
/// key — so callers merging array positions ([`merge_arrays_by_index`])
/// pass `false`, while object-field callers ([`merge_object_fields`]) pass
/// `true`.
fn merge_position(
    existing: Option<OwnedValue>,
    incoming: OwnedValue,
    flags: MergeFlags,
    only_existing_applies: bool,
) -> Option<OwnedValue> {
    match existing {
        None => {
            if flags.only_existing && only_existing_applies {
                None
            } else {
                Some(incoming)
            }
        }
        Some(existing) => Some(merge_existing(existing, incoming, flags)),
    }
}

/// Merge `right`'s fields into `left`, one position at a time via
/// [`merge_position`]. Uses the `Entry` API rather than
/// `left.get(&k).cloned()` + `left.insert(..)` so an existing value that's
/// itself a large nested container moves into the merge instead of being
/// deep-cloned first.
fn merge_object_fields(
    mut left: IndexMap<String, OwnedValue>,
    right: IndexMap<String, OwnedValue>,
    flags: MergeFlags,
) -> IndexMap<String, OwnedValue> {
    for (k, v) in right {
        match left.entry(k) {
            indexmap::map::Entry::Occupied(mut e) => {
                let existing = e.insert(OwnedValue::Null);
                e.insert(merge_existing(existing, v, flags));
            }
            indexmap::map::Entry::Vacant(e) => {
                if let Some(new_value) = merge_position(None, v, flags, true) {
                    e.insert(new_value);
                }
            }
        }
    }
    left
}

/// Deep-merge two arrays by index (the `d` flag): treats the array like an
/// object keyed by index, one position at a time via [`merge_existing`].
/// Indices only present in `right` extend `left` — real yq's `?` never
/// blocks this (see [`merge_position`]'s doc comment), so extension is
/// unconditional here rather than routed through `merge_position`.
fn merge_arrays_by_index(
    mut left: Vec<OwnedValue>,
    right: Vec<OwnedValue>,
    flags: MergeFlags,
) -> Vec<OwnedValue> {
    for (i, v) in right.into_iter().enumerate() {
        if i < left.len() {
            let existing = core::mem::replace(&mut left[i], OwnedValue::Null);
            left[i] = merge_existing(existing, v, flags);
        } else {
            left.push(v);
        }
    }
    left
}

/// Divide two values.
fn arith_div<S: EvalSemantics>(
    left: OwnedValue,
    right: OwnedValue,
) -> Result<OwnedValue, EvalError> {
    let (left, right) = (left.into_plain_number(), right.into_plain_number());
    match (left, right) {
        (OwnedValue::Int(a), OwnedValue::Int(b)) => {
            if b == 0 {
                if S::DIV_BY_ZERO_IS_INFINITY {
                    // yq behavior: return infinity
                    Ok(OwnedValue::Float(a as f64 / b as f64))
                } else {
                    // jq behavior: error
                    Err(EvalError::divisor_is_zero(
                        &OwnedValue::Int(a),
                        &OwnedValue::Int(b),
                        BinOp::Divide,
                    ))
                }
            } else {
                Ok(OwnedValue::Float(a as f64 / b as f64))
            }
        }
        (OwnedValue::Int(a), OwnedValue::Float(b)) => {
            if b == 0.0 && !S::DIV_BY_ZERO_IS_INFINITY {
                Err(EvalError::divisor_is_zero(
                    &OwnedValue::Int(a),
                    &OwnedValue::Float(b),
                    BinOp::Divide,
                ))
            } else {
                Ok(OwnedValue::Float(a as f64 / b))
            }
        }
        (OwnedValue::Float(a), OwnedValue::Int(b)) => {
            if b == 0 && !S::DIV_BY_ZERO_IS_INFINITY {
                Err(EvalError::divisor_is_zero(
                    &OwnedValue::Float(a),
                    &OwnedValue::Int(b),
                    BinOp::Divide,
                ))
            } else {
                Ok(OwnedValue::Float(a / b as f64))
            }
        }
        (OwnedValue::Float(a), OwnedValue::Float(b)) => {
            if b == 0.0 && !S::DIV_BY_ZERO_IS_INFINITY {
                Err(EvalError::divisor_is_zero(
                    &OwnedValue::Float(a),
                    &OwnedValue::Float(b),
                    BinOp::Divide,
                ))
            } else {
                Ok(OwnedValue::Float(a / b))
            }
        }
        // String split: "a,b,c" / "," = ["a", "b", "c"]
        (OwnedValue::String(s), OwnedValue::String(sep)) => {
            let parts: Vec<OwnedValue> = s
                .split(&sep)
                .map(|p| OwnedValue::String(p.to_string()))
                .collect();
            Ok(OwnedValue::Array(parts))
        }
        (a, b) => Err(EvalError::binary_op(&a, &b, BinOp::Divide)),
    }
}

/// Modulo two values.
fn arith_mod<S: EvalSemantics>(
    left: OwnedValue,
    right: OwnedValue,
) -> Result<OwnedValue, EvalError> {
    let (left, right) = (left.into_plain_number(), right.into_plain_number());
    match (left, right) {
        (OwnedValue::Int(a), OwnedValue::Int(b)) => {
            if b == 0 {
                if S::DIV_BY_ZERO_IS_INFINITY {
                    // yq behavior: return NaN (will be serialized as null)
                    Ok(OwnedValue::Float(f64::NAN))
                } else {
                    // jq behavior: error
                    Err(EvalError::divisor_is_zero(
                        &OwnedValue::Int(a),
                        &OwnedValue::Int(b),
                        BinOp::Modulo,
                    ))
                }
            } else {
                Ok(OwnedValue::Int(a.wrapping_rem(b)))
            }
        }
        (OwnedValue::Float(a), OwnedValue::Float(b)) => {
            mod_floats::<S>(a, b, &OwnedValue::Float(a), &OwnedValue::Float(b))
        }
        (OwnedValue::Int(a), OwnedValue::Float(b)) => {
            mod_floats::<S>(a as f64, b, &OwnedValue::Int(a), &OwnedValue::Float(b))
        }
        (OwnedValue::Float(a), OwnedValue::Int(b)) => {
            mod_floats::<S>(a, b as f64, &OwnedValue::Float(a), &OwnedValue::Int(b))
        }
        (a, b) => Err(EvalError::binary_op(&a, &b, BinOp::Modulo)),
    }
}

/// Modulo where at least one operand is a float.
///
/// jq truncates both operands to integers (`intmax_t`), so `10.5 % 3 == 1` and
/// `5 % 0.5` errors because the divisor truncates to zero. yq performs float
/// modulo, returning NaN for a zero divisor.
fn mod_floats<S: EvalSemantics>(
    a: f64,
    b: f64,
    left: &OwnedValue,
    right: &OwnedValue,
) -> Result<OwnedValue, EvalError> {
    if S::MOD_TRUNCATES_FLOATS {
        if a.is_nan() || b.is_nan() {
            return Ok(OwnedValue::Float(f64::NAN));
        }
        // `as` truncates toward zero and saturates, matching jq's intmax_t cast.
        let (ai, bi) = (a as i64, b as i64);
        if bi == 0 {
            Err(EvalError::divisor_is_zero(left, right, BinOp::Modulo))
        } else {
            // wrapping_rem: i64::MIN % -1 must not panic.
            Ok(OwnedValue::Int(ai.wrapping_rem(bi)))
        }
    } else if b == 0.0 && !S::DIV_BY_ZERO_IS_INFINITY {
        Err(EvalError::divisor_is_zero(left, right, BinOp::Modulo))
    } else {
        Ok(OwnedValue::Float(a % b))
    }
}

/// Evaluate comparison operations.
fn eval_compare<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    op: CompareOp,
    left: &Expr,
    right: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    eval_binary_fanout::<W, S>(left, right, value, optional, |left_val, right_val| {
        Ok(OwnedValue::Bool(apply_compare_op(
            op, &left_val, &right_val,
        )))
    })
}

/// Apply a comparison operator to two already-evaluated values.
///
/// Factored out of [`eval_compare`] so the path-context evaluator's own
/// `Expr::Compare` arm (`eval_pipe_with_path_context_internal`, #715) can
/// reuse the exact same operator semantics rather than a second, divergence-
/// prone copy -- see the project's own "one definition, plus a test that call
/// sites agree" convention (already applied to `compare_values` itself).
fn apply_compare_op(op: CompareOp, left: &OwnedValue, right: &OwnedValue) -> bool {
    match op {
        CompareOp::Eq => left == right,
        CompareOp::Ne => left != right,
        CompareOp::Lt => compare_values(left, right) == core::cmp::Ordering::Less,
        CompareOp::Le => compare_values(left, right) != core::cmp::Ordering::Greater,
        CompareOp::Gt => compare_values(left, right) == core::cmp::Ordering::Greater,
        CompareOp::Ge => compare_values(left, right) != core::cmp::Ordering::Less,
    }
}

/// Compare two values using jq ordering: null < bool < number < string < array < object.
///
/// The one definition of this ordering in the jq module -- shared with the
/// generic (CLI) evaluator, which imports this rather than keeping its own
/// copy (#421, following the #358/#384 precedent: one definition, plus a test
/// that call sites agree).
///
/// NaN orders as strictly less than every other number, including another
/// NaN -- see [`cmp_f64`](super::value::cmp_f64)'s doc comment for the full
/// truth table. That makes this comparator *not* a strict weak ordering
/// whenever two NaNs are compared against each other, which
/// `sort`/`sort_by`/`unique`/`unique_by`/`group_by` feed straight into
/// `[T]::sort_by`. In practice the risk is narrow: `[T]::sort_by` only
/// reaches the internal check that can panic on such a comparator
/// (`core::slice::sort::shared::smallsort`'s bidirectional-merge consistency
/// check) for slices longer than 20 elements --
/// `MAX_LEN_ALWAYS_INSERTION_SORT` in the current standard library, an
/// implementation detail, not a stable contract. Anything at or below that
/// length uses plain insertion sort, which cannot panic regardless of
/// comparator validity, and stress-testing (1,510 randomized/adversarial
/// trials up to length 5000 and 90% NaN density) found no panics at any size.
/// `min`/`max`/`min_by`/`max_by` never sort (`Iterator::min_by`/`max_by` fold
/// left-to-right) and `unique`'s/`unique_by`'s `dedup_by` only compares
/// adjacent elements, so neither has any panic surface at all. See
/// `test_sort_many_nans_does_not_panic_421`.
pub(crate) fn compare_values(left: &OwnedValue, right: &OwnedValue) -> core::cmp::Ordering {
    use core::cmp::Ordering;

    let left_type = sort_rank(left);
    let right_type = sort_rank(right);

    if left_type != right_type {
        return left_type.cmp(&right_type);
    }

    match (left, right) {
        (OwnedValue::Null, OwnedValue::Null) => Ordering::Equal,
        (OwnedValue::Bool(a), OwnedValue::Bool(b)) => a.cmp(b),
        (OwnedValue::Int(a), OwnedValue::Int(b)) => a.cmp(b),
        (OwnedValue::Float(a), OwnedValue::Float(b)) => cmp_f64(*a, *b),
        (OwnedValue::Int(a), OwnedValue::Float(b)) => cmp_f64(*a as f64, *b),
        (OwnedValue::Float(a), OwnedValue::Int(b)) => cmp_f64(*a, *b as f64),
        // A `NumberLiteral` operand compares by its parsed value, exactly
        // like `Int`/`Float` -- ordering never looks at the source text.
        // `numeric_repr_cmp` dispatches on the same `(Int,Int)`/`(Float,Float)`/
        // mixed pairing `==` uses (`numeric_repr_eq`), so ordering can't
        // disagree with equality about the same pair (see its doc comment).
        (OwnedValue::NumberLiteral(..), _) | (_, OwnedValue::NumberLiteral(..)) => {
            match (left.number_repr(), right.number_repr()) {
                (Some(a), Some(b)) => numeric_repr_cmp(a, b),
                _ => Ordering::Equal,
            }
        }
        (OwnedValue::String(a), OwnedValue::String(b)) => a.cmp(b),
        (OwnedValue::Array(a), OwnedValue::Array(b)) => {
            for (av, bv) in a.iter().zip(b.iter()) {
                match compare_values(av, bv) {
                    Ordering::Equal => continue,
                    other => return other,
                }
            }
            a.len().cmp(&b.len())
        }
        (OwnedValue::Object(a), OwnedValue::Object(b)) => {
            // jq compares the sorted key arrays first, then values in
            // sorted-key order.
            let mut a_keys: Vec<&String> = a.keys().collect();
            let mut b_keys: Vec<&String> = b.keys().collect();
            a_keys.sort();
            b_keys.sort();
            match a_keys.cmp(&b_keys) {
                Ordering::Equal => {}
                other => return other,
            }
            for k in a_keys {
                match compare_values(&a[k], &b[k]) {
                    Ordering::Equal => continue,
                    other => return other,
                }
            }
            Ordering::Equal
        }
        _ => Ordering::Equal,
    }
}

/// Evaluate boolean AND (short-circuiting).
fn eval_and<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    left: &Expr,
    right: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // `false and _` is false without consulting the right operand.
    eval_boolean::<W, S>(left, right, value, optional, false)
}

/// Evaluate boolean OR (short-circuiting).
fn eval_or<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    left: &Expr,
    right: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // `true or _` is true without consulting the right operand.
    eval_boolean::<W, S>(left, right, value, optional, true)
}

/// Shared body of `and` and `or`, which differ only in which truth value
/// short-circuits: `false` for `and`, `true` for `or`.
///
/// Both are generators, not scalar operators (#160). jq emits one boolean per
/// (left output, right output) pair, with the left operand as the outer loop:
/// `(true,false) and (true,false)` yields `true false false` because the second
/// left output short-circuits. A left output that short-circuits contributes
/// its boolean without evaluating the right operand at all, which is what makes
/// `false and error("x")` yield `false` rather than raising.
///
/// The right operand is re-evaluated per left output rather than evaluated once
/// and reused. That matches jq's backtracking, and it costs nothing in the
/// common case where the left operand is single-output.
///
/// An error or a break in either operand no longer discards `out` (#400,
/// #494): a left operand that errors after producing some truthy values
/// (e.g. `(true,error("x")) and false`) still pairs those left values against
/// the right operand before the error surfaces — jq emits `false`, then
/// errors — so `left`'s own trailing control is held in `left_control` and
/// only applied once the ordinary per-left-output loop has run its course. A
/// control from evaluating the right operand for a given left output instead
/// ends the whole expression immediately, matching jq's generator not asking
/// for further left outputs once one pairing has failed.
fn eval_boolean<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    left: &Expr,
    right: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
    short_circuit: bool,
) -> QueryResult<'a, W> {
    let mut left_bools = Vec::new();
    let left_control = push_truthiness(
        eval_single::<W, S>(left, value.clone(), optional),
        &mut left_bools,
    );

    let mut out = Vec::with_capacity(left_bools.len());
    for left_bool in left_bools {
        if left_bool == short_circuit {
            out.push(short_circuit);
            continue;
        }
        if let Some(control) = push_truthiness(
            eval_single::<W, S>(right, value.clone(), optional),
            &mut out,
        ) {
            return partial(out.into_iter().map(OwnedValue::Bool).collect(), control);
        }
    }

    match left_control {
        Some(control) => partial(out.into_iter().map(OwnedValue::Bool).collect(), control),
        None => bools_to_result(out),
    }
}

/// Evaluate boolean NOT.
fn eval_not<W: Clone + AsRef<[u64]>>(value: StandardJson<'_, W>) -> QueryResult<'_, W> {
    let owned = to_owned(&value);
    QueryResult::Owned(OwnedValue::Bool(!owned.is_truthy()))
}

/// Evaluate alternative operator (`//`).
///
/// `a // b` emits **every** output of `a` that is neither `null` nor `false`,
/// and only when `a` yields no such output does it evaluate `b` (#160). `b`'s
/// outputs are emitted unfiltered — `false // (null,7)` is `null, 7` — which is
/// what makes the left-associative chain `a // b // c` filter `b`'s stream.
fn eval_alternative<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    left: &Expr,
    right: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    match retain_truthy(eval_single::<W, S>(left, value.clone(), optional)) {
        // A `break` escapes the operator rather than selecting a branch.
        QueryResult::Break(label) => QueryResult::Break(label),
        // No truthy output on the left, so the right side answers.
        QueryResult::None => eval_single::<W, S>(right, value, optional),
        // An error on the left propagates, matching jq 1.7.1: `//` only
        // substitutes for falsy/absent output, not for a raised error. Use
        // `?` on the left (e.g. `.a? // 3`) to suppress the error instead.
        error @ QueryResult::Error(_) => error,
        kept => kept,
    }
}

/// Evaluate if-then-else expression.
///
/// A multi-output condition forks the branches, one evaluation per output
/// (`if (true,false) then "a" else "b" end` yields `"a"`, `"b"`) — jq
/// semantics, restored by `eval_fanout` (#378).
fn eval_if<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    cond: &Expr,
    then_branch: &Expr,
    else_branch: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    let cond_result = eval_single::<W, S>(cond, value.clone(), optional);
    eval_fanout(cond_result, |truthy| {
        if truthy {
            eval_single::<W, S>(then_branch, value.clone(), optional)
        } else {
            eval_single::<W, S>(else_branch, value.clone(), optional)
        }
    })
}

/// Evaluate try-catch expression.
fn eval_try<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    expr: &Expr,
    catch: Option<&Expr>,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // Evaluate the expression
    let result = eval_single::<W, S>(expr, value, optional);

    match result {
        // If error, use catch handler or return nothing. jq runs the handler
        // with the *raised value* as its input, not the original input, so
        // `try error("boom") catch .` yields "boom".
        QueryResult::Error(e) => match catch {
            Some(catch_expr) => eval_owned_input::<W, S>(catch_expr, &e.payload(), optional),
            None => QueryResult::None,
        },
        // jq's `catch` catches a `break` the same way it catches a raised
        // error, regardless of which label it targets (#562). Real jq binds
        // the catch handler's input to its internal `{"__jq":N}` break
        // marker — an implementation detail not worth replicating — so bind
        // `null` instead.
        QueryResult::Break(_) => match catch {
            Some(catch_expr) => eval_owned_input::<W, S>(catch_expr, &OwnedValue::Null, optional),
            None => QueryResult::None,
        },
        // The body produced some outputs before erroring (#400): emit them
        // (`try (1,2,error("x")) catch "c"` is `1`, `2`, `"c"`), then run the
        // catch handler and splice its own result — which may itself be
        // `Partial` if the handler errors too — in after them.
        QueryResult::Partial(prefix, Control::Error(e)) => {
            let handled = match catch {
                Some(catch_expr) => eval_owned_input::<W, S>(catch_expr, &e.payload(), optional),
                None => QueryResult::None,
            };
            prepend(prefix, handled)
        }
        // Same as the plain `Break` case above (#562), but the body
        // produced outputs before breaking: emit them, then run the catch
        // handler bound to `null` and splice its result in after them.
        QueryResult::Partial(prefix, Control::Break(_)) => {
            let handled = match catch {
                Some(catch_expr) => {
                    eval_owned_input::<W, S>(catch_expr, &OwnedValue::Null, optional)
                }
                None => QueryResult::None,
            };
            prepend(prefix, handled)
        }
        // Non-error, non-break results pass through
        other => other,
    }
}

/// Evaluate label expression.
/// `label $name | expr` establishes a scope that can be exited with `break $name`.
fn eval_label<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    name: &str,
    body: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    let result = eval_single::<W, S>(body, value, optional);
    match result {
        // If we get a Break with matching label, convert to empty output
        QueryResult::Break(label) if label == name => QueryResult::None,
        // A matching break that already carries a prefix (#400): emit the
        // outputs the body produced before breaking, dropping the control —
        // `label $out | 1,2,break $out,4` is `1`, `2`.
        QueryResult::Partial(prefix, Control::Break(label)) if label == name => {
            owned_vec_to_result(prefix)
        }
        // Non-matching breaks (bare or `Partial`) propagate up unchanged.
        other => other,
    }
}

/// Evaluate error expression.
fn eval_error<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    msg: Option<&Expr>,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // The payload is raised verbatim so `catch` can inspect it, and so the CLI
    // can flag a non-string one; `EvalError` renders the message from it. Bare
    // `error` raises the input value, as jq does — `{"x":1} | error` reports
    // `{"x":1}`, not `null`.
    let payload = match msg {
        Some(msg_expr) => {
            let msg_result = eval_single::<W, S>(msg_expr, value, optional);
            match result_to_owned(msg_result) {
                Ok(v) => v,
                // `?` swallows only a genuine error in the message
                // expression; a halt inside it always escapes (#791) —
                // `isvalid(error(halt_error(3)))` must still halt, not
                // report `false`.
                Err(EvalEscape::Error(_)) if optional => return QueryResult::None,
                Err(escape) => return escape.into(),
            }
        }
        None => to_owned(&value),
    };

    if optional {
        QueryResult::None
    } else {
        QueryResult::Error(EvalError::from_value(payload))
    }
}

/// Evaluate a builtin function.
fn eval_builtin<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    builtin: &Builtin,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    match builtin {
        // Type functions
        Builtin::Type => {
            let type_name = match &value {
                StandardJson::Null => "null",
                StandardJson::Bool(_) => "boolean",
                StandardJson::Number(_) => "number",
                StandardJson::String(_) => "string",
                StandardJson::Array(_) => "array",
                StandardJson::Object(_) => "object",
                StandardJson::Error(_) => "error",
            };
            QueryResult::Owned(OwnedValue::String(type_name.into()))
        }
        Builtin::IsNull => {
            QueryResult::Owned(OwnedValue::Bool(matches!(value, StandardJson::Null)))
        }
        Builtin::IsBoolean => {
            QueryResult::Owned(OwnedValue::Bool(matches!(value, StandardJson::Bool(_))))
        }
        Builtin::IsNumber => {
            QueryResult::Owned(OwnedValue::Bool(matches!(value, StandardJson::Number(_))))
        }
        Builtin::IsString => {
            QueryResult::Owned(OwnedValue::Bool(matches!(value, StandardJson::String(_))))
        }
        Builtin::IsArray => {
            QueryResult::Owned(OwnedValue::Bool(matches!(value, StandardJson::Array(_))))
        }
        Builtin::IsObject => {
            QueryResult::Owned(OwnedValue::Bool(matches!(value, StandardJson::Object(_))))
        }

        // Type filter functions (select by type)
        // These return the input unchanged if the type matches, or nothing otherwise
        Builtin::Values => {
            // values - select non-null values
            if matches!(value, StandardJson::Null) {
                QueryResult::None
            } else {
                QueryResult::One(value)
            }
        }
        Builtin::Nulls => {
            // nulls - select only null values
            if matches!(value, StandardJson::Null) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }
        Builtin::Booleans => {
            // booleans - select only boolean values
            if matches!(value, StandardJson::Bool(_)) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }
        Builtin::Numbers => {
            // numbers - select only number values
            if matches!(value, StandardJson::Number(_)) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }
        Builtin::Strings => {
            // strings - select only string values
            if matches!(value, StandardJson::String(_)) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }
        Builtin::Arrays => {
            // arrays - select only array values
            if matches!(value, StandardJson::Array(_)) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }
        Builtin::Objects => {
            // objects - select only object values
            if matches!(value, StandardJson::Object(_)) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }
        Builtin::Iterables => {
            // iterables - select arrays and objects
            if matches!(value, StandardJson::Array(_) | StandardJson::Object(_)) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }
        Builtin::Scalars => {
            // scalars - select non-iterables (null, bool, number, string)
            if matches!(
                value,
                StandardJson::Null
                    | StandardJson::Bool(_)
                    | StandardJson::Number(_)
                    | StandardJson::String(_)
            ) {
                QueryResult::One(value)
            } else {
                QueryResult::None
            }
        }

        // Length & Keys
        Builtin::Length => builtin_length::<W>(value, optional),
        Builtin::Utf8ByteLength => builtin_utf8bytelength(value, optional),
        Builtin::Keys => builtin_keys::<W>(value, optional, true),
        Builtin::KeysUnsorted => builtin_keys::<W>(value, optional, false),
        Builtin::Has(key_expr) => builtin_has::<W, S>(key_expr, value, optional),
        Builtin::In(obj_expr) => builtin_in::<W, S>(obj_expr, value, optional),
        Builtin::UpperIn(s) => builtin_upper_in::<W, S>(s, value, optional),
        Builtin::UpperInSrc(src, s) => builtin_upper_in_src::<W, S>(src, s, value, optional),

        // Selection & Filtering
        Builtin::Select(cond) => builtin_select::<W, S>(cond, value, optional),
        Builtin::Empty => QueryResult::None,

        // Map & Iteration
        Builtin::Map(f) => builtin_map::<W, S>(f, value, optional),
        Builtin::MapValues(f) => builtin_map_values::<W, S>(f, value, optional),

        // Reduction
        Builtin::Add => builtin_add::<W, S>(value, optional),
        Builtin::Any => builtin_any::<W>(value, optional),
        Builtin::AnyF(cond) => builtin_any_f::<W, S>(cond, value, optional),
        Builtin::AnyCond(gen, cond) => builtin_any_cond::<W, S>(gen, cond, value, optional),
        Builtin::All => builtin_all::<W>(value, optional),
        Builtin::AllF(cond) => builtin_all_f::<W, S>(cond, value, optional),
        Builtin::AllCond(gen, cond) => builtin_all_cond::<W, S>(gen, cond, value, optional),
        Builtin::Min => builtin_min::<W>(value, optional),
        Builtin::Max => builtin_max::<W>(value, optional),
        Builtin::MinBy(f) => builtin_min_by::<W, S>(f, value, optional),
        Builtin::MaxBy(f) => builtin_max_by::<W, S>(f, value, optional),

        // Phase 5: String Functions
        Builtin::AsciiDowncase => builtin_ascii_downcase::<W>(value, optional),
        Builtin::AsciiUpcase => builtin_ascii_upcase::<W>(value, optional),
        Builtin::Ltrimstr(s) => builtin_ltrimstr::<W, S>(s, value, optional),
        Builtin::Rtrimstr(s) => builtin_rtrimstr::<W, S>(s, value, optional),
        Builtin::Startswith(s) => builtin_startswith::<W, S>(s, value, optional),
        Builtin::Endswith(s) => builtin_endswith::<W, S>(s, value, optional),
        Builtin::Split(sep) => builtin_split::<W, S>(sep, value, optional),
        Builtin::Join(sep) => builtin_join::<W, S>(sep, value, optional),
        Builtin::Contains(b) => builtin_contains::<W, S>(b, value, optional),
        Builtin::Inside(b) => builtin_inside::<W, S>(b, value, optional),

        // Phase 5: Array Functions
        Builtin::First => builtin_first::<W>(value, optional),
        Builtin::Last => builtin_last::<W>(value, optional),
        Builtin::Nth(n) => builtin_nth::<W, S>(n, value, optional),
        Builtin::Reverse => builtin_reverse::<W>(value, optional),
        Builtin::Flatten => builtin_flatten::<W>(value, optional, 1),
        Builtin::FlattenDepth(depth) => builtin_flatten_depth::<W, S>(depth, value, optional),
        Builtin::GroupBy(f) => builtin_group_by::<W, S>(f, value, optional),
        Builtin::Unique => builtin_unique::<W>(value, optional),
        Builtin::UniqueBy(f) => builtin_unique_by::<W, S>(f, value, optional),
        Builtin::Sort => builtin_sort::<W>(value, optional),
        Builtin::SortBy(f) => builtin_sort_by::<W, S>(f, value, optional),

        // Phase 5: Object Functions
        Builtin::ToEntries => builtin_to_entries::<W>(value, optional),
        Builtin::FromEntries => builtin_from_entries::<W>(value, optional),
        Builtin::WithEntries(f) => builtin_with_entries::<W, S>(f, value, optional),

        // Phase 6: Type Conversions
        Builtin::ToString => builtin_tostring::<W>(value, optional),
        Builtin::ToNumber => builtin_tonumber::<W>(value, optional),
        Builtin::ToJson => builtin_tojson::<W>(value, optional),
        Builtin::FromJson => builtin_fromjson::<W>(value, optional),

        // Phase 6: Additional String Functions
        Builtin::Explode => builtin_explode::<W>(value, optional),
        Builtin::Implode => builtin_implode::<W>(value, optional),
        #[cfg(feature = "regex")]
        Builtin::Test(re) => builtin_test_regex::<W, S>(re, value, optional),
        #[cfg(not(feature = "regex"))]
        Builtin::Test(re) => builtin_test::<W, S>(re, value, optional),
        Builtin::Indices(s) => builtin_indices::<W, S>(s, value, optional),
        Builtin::Index(s) => builtin_index::<W, S>(s, value, optional),
        Builtin::Rindex(s) => builtin_rindex::<W, S>(s, value, optional),
        Builtin::UpperIndex(idx_expr) => builtin_upper_index::<W, S>(idx_expr, value, optional),
        Builtin::UpperIndexStream(stream, idx_expr) => {
            builtin_upper_index_stream::<W, S>(stream, idx_expr, value, optional)
        }
        Builtin::ToJsonStream => builtin_tojsonstream::<W>(value, optional),
        Builtin::FromJsonStream => builtin_fromjsonstream::<W>(value, optional),
        Builtin::ToStream => builtin_tostream::<W>(value, optional),
        Builtin::FromStream(f) => builtin_fromstream::<W, S>(f, value, optional),
        Builtin::TruncateStream(f) => builtin_truncate_stream::<W, S>(f, value, optional),
        Builtin::GetPath(path) => builtin_getpath::<W, S>(path, value, optional),

        // Phase 16: Regex Functions
        #[cfg(feature = "regex")]
        Builtin::TestFlags(re, flags) => builtin_test_flags::<W, S>(re, flags, value, optional),
        #[cfg(feature = "regex")]
        Builtin::Match(re) => builtin_match::<W, S>(re, None, value, optional),
        #[cfg(feature = "regex")]
        Builtin::MatchFlags(re, flags) => builtin_match_flags::<W, S>(re, flags, value, optional),
        #[cfg(feature = "regex")]
        Builtin::Capture(re) => builtin_capture_with_flags::<W, S>(re, None, value, optional),
        #[cfg(feature = "regex")]
        Builtin::CaptureFlags(re, flags) => {
            builtin_capture_flags::<W, S>(re, flags, value, optional)
        }
        #[cfg(feature = "regex")]
        Builtin::Sub(re, replacement) => builtin_sub::<W, S>(re, replacement, value, optional),
        #[cfg(feature = "regex")]
        Builtin::SubFlags(re, replacement, flags) => {
            builtin_sub_flags::<W, S>(re, replacement, flags, value, optional)
        }
        #[cfg(feature = "regex")]
        Builtin::Gsub(re, replacement) => builtin_gsub::<W, S>(re, replacement, value, optional),
        #[cfg(feature = "regex")]
        Builtin::GsubFlags(re, replacement, flags) => {
            builtin_gsub_flags::<W, S>(re, replacement, flags, value, optional)
        }
        #[cfg(feature = "regex")]
        Builtin::Scan(re) => builtin_scan::<W, S>(re, value, optional),
        #[cfg(feature = "regex")]
        Builtin::ScanFlags(re, flags) => builtin_scan_flags::<W, S>(re, flags, value, optional),
        #[cfg(feature = "regex")]
        Builtin::SplitRegex(re, flags) => builtin_split_regex::<W, S>(re, flags, value, optional),
        #[cfg(feature = "regex")]
        Builtin::Splits(re) => builtin_splits::<W, S>(re, value, optional),
        #[cfg(feature = "regex")]
        Builtin::SplitsFlags(re, flags) => builtin_splits_flags::<W, S>(re, flags, value, optional),
        // Non-regex fallbacks for when regex feature is not enabled
        #[cfg(not(feature = "regex"))]
        Builtin::TestFlags(_, _)
        | Builtin::Match(_)
        | Builtin::MatchFlags(_, _)
        | Builtin::Capture(_)
        | Builtin::CaptureFlags(_, _)
        | Builtin::Sub(_, _)
        | Builtin::SubFlags(_, _, _)
        | Builtin::Gsub(_, _)
        | Builtin::GsubFlags(_, _, _)
        | Builtin::Scan(_)
        | Builtin::ScanFlags(_, _)
        | Builtin::SplitRegex(_, _)
        | Builtin::Splits(_)
        | Builtin::SplitsFlags(_, _) => {
            QueryResult::Error(EvalError::new("regex feature not enabled"))
        }

        // Phase 8: Advanced Control Flow Builtins
        Builtin::Recurse => builtin_recurse::<W, S>(value, optional),
        Builtin::RecurseF(f) => builtin_recurse_f::<W, S>(f, value, optional),
        Builtin::RecurseCond(f, cond) => builtin_recurse_cond::<W, S>(f, cond, value, optional),
        Builtin::Walk(f) => builtin_walk::<W, S>(f, value, optional),
        Builtin::IsValid(expr) => builtin_isvalid::<W, S>(expr, value, optional),

        // Phase 10: Path Expressions
        Builtin::Path(expr) => builtin_path::<W, S>(expr, value, optional),
        Builtin::PathNoArg => {
            // PathNoArg requires path context which is handled in eval_pipe_with_context
            // When called without context, return empty path (root position)
            QueryResult::Owned(OwnedValue::Array(vec![]))
        }
        Builtin::Parent => {
            // Parent requires path context which is handled in eval_pipe_with_context
            // When called without context, return empty object (no parent at root)
            QueryResult::Owned(OwnedValue::Object(IndexMap::new()))
        }
        Builtin::ParentN(n_expr) => {
            // ParentN requires path context which is handled in eval_pipe_with_context
            // When called without context, return empty object
            let _ = n_expr; // Unused here, but evaluated in context version
            QueryResult::Owned(OwnedValue::Object(IndexMap::new()))
        }
        Builtin::Paths => builtin_paths::<W>(value, optional),
        Builtin::PathsFilter(filter) => builtin_paths_filter::<W, S>(filter, value, optional),
        Builtin::LeafPaths => builtin_leaf_paths::<W>(value, optional),
        Builtin::SetPath(path, val) => builtin_setpath::<W, S>(path, val, value, optional),
        Builtin::DelPaths(paths) => builtin_delpaths::<W, S>(paths, value, optional),

        // Phase 10: Math Functions
        Builtin::Floor => builtin_floor::<W>(value, optional),
        Builtin::Ceil => builtin_ceil::<W>(value, optional),
        Builtin::Round => builtin_round::<W>(value, optional),
        Builtin::Sqrt => builtin_sqrt::<W>(value, optional),
        Builtin::Fabs => builtin_fabs::<W>(value, optional),
        Builtin::Log => builtin_log::<W>(value, optional),
        Builtin::Log10 => builtin_log10::<W>(value, optional),
        Builtin::Log2 => builtin_log2::<W>(value, optional),
        Builtin::Exp => builtin_exp::<W>(value, optional),
        Builtin::Exp10 => builtin_exp10::<W>(value, optional),
        Builtin::Exp2 => builtin_exp2::<W>(value, optional),
        Builtin::Pow(base, exp) => builtin_pow::<W, S>(base, exp, value, optional),
        Builtin::Sin => builtin_sin::<W>(value, optional),
        Builtin::Cos => builtin_cos::<W>(value, optional),
        Builtin::Tan => builtin_tan::<W>(value, optional),
        Builtin::Asin => builtin_asin::<W>(value, optional),
        Builtin::Acos => builtin_acos::<W>(value, optional),
        Builtin::Atan => builtin_atan::<W>(value, optional),
        Builtin::Atan2(y, x) => builtin_atan2::<W, S>(y, x, value, optional),
        Builtin::Sinh => builtin_sinh::<W>(value, optional),
        Builtin::Cosh => builtin_cosh::<W>(value, optional),
        Builtin::Tanh => builtin_tanh::<W>(value, optional),
        Builtin::Asinh => builtin_asinh::<W>(value, optional),
        Builtin::Acosh => builtin_acosh::<W>(value, optional),
        Builtin::Atanh => builtin_atanh::<W>(value, optional),

        // Phase 10: Number Classification & Constants
        Builtin::Infinite => QueryResult::Owned(OwnedValue::Float(f64::INFINITY)),
        Builtin::Nan => QueryResult::Owned(OwnedValue::Float(f64::NAN)),
        Builtin::IsInfinite => builtin_isinfinite::<W>(value, optional),
        Builtin::IsNan => builtin_isnan::<W>(value, optional),
        Builtin::IsNormal => builtin_isnormal::<W>(value, optional),
        Builtin::IsFinite => builtin_isfinite::<W>(value, optional),

        // Phase 10: Debug
        Builtin::Debug => builtin_debug::<W>(value, optional),
        Builtin::DebugMsg(msg) => builtin_debug_msg::<W, S>(msg, value, optional),

        // Process control (#791)
        Builtin::Halt => builtin_halt::<W>(),
        Builtin::Stderr => builtin_stderr::<W>(value, optional),
        Builtin::HaltError => builtin_halt_error::<W, S>(None, value, optional),
        Builtin::HaltErrorCode(code) => builtin_halt_error::<W, S>(Some(code), value, optional),

        // Phase 10: Environment
        Builtin::Env => builtin_env::<W>(value, optional),
        Builtin::EnvVar(var) => builtin_envvar::<W, S>(var, value, optional),
        Builtin::EnvObject(name) => builtin_env_object::<W>(name, optional),
        Builtin::StrEnv(name) => builtin_strenv::<W>(name, optional),

        // Phase 10: Null handling
        Builtin::NullLit => QueryResult::Owned(OwnedValue::Null),

        // Phase 10: String functions
        Builtin::Trim => builtin_trim::<W>(value, optional),
        Builtin::Ltrim => builtin_ltrim::<W>(value, optional),
        Builtin::Rtrim => builtin_rtrim::<W>(value, optional),

        // Phase 10: Array functions
        Builtin::Transpose => builtin_transpose::<W>(value, optional),
        Builtin::BSearch(x) => builtin_bsearch::<W, S>(x, value, optional),

        // Phase 10: Object functions
        Builtin::ModuleMeta(name) => builtin_modulemeta::<W>(name, value, optional),
        Builtin::Pick(keys) => builtin_pick::<W, S>(keys, value, optional),
        Builtin::Omit(keys) => builtin_omit::<W, S>(keys, value, optional),

        // YAML metadata functions (yq)
        Builtin::Tag => builtin_tag::<W>(value),
        Builtin::Anchor => builtin_anchor::<W>(),
        Builtin::Style => builtin_style::<W>(),
        Builtin::Kind => builtin_kind::<W>(value),
        Builtin::Line => builtin_line::<W>(),
        Builtin::Column => builtin_column::<W>(),
        Builtin::DocumentIndex => builtin_document_index::<W>(),
        Builtin::LineComment => builtin_line_comment::<W>(),
        Builtin::FileIndex => {
            // Requires the `--eval-all` path-context evaluator to resolve to
            // anything but 0; reached here means either outside `--eval-all`
            // or nested in a shape that evaluator doesn't cover (#715), the
            // same documented "0 outside supported context" contract
            // `document_index` already has.
            QueryResult::Owned(OwnedValue::Int(0))
        }
        Builtin::Shuffle => builtin_shuffle::<W>(value, optional),
        Builtin::Pivot => builtin_pivot::<W>(value, optional),
        Builtin::SplitDoc => {
            // split_doc is identity - the output formatting (--- separators)
            // is handled by the yq runner, not here
            QueryResult::One(value.clone())
        }
        Builtin::Key => {
            // Key requires path context which is handled in eval_pipe_with_context
            // If we reach here without context, return null (at root level)
            QueryResult::Owned(OwnedValue::Null)
        }

        // Phase 11: Path manipulation
        Builtin::Del(path) => builtin_del::<W, S>(path, value, optional),

        // Phase 12: Additional builtins
        Builtin::Now => builtin_now::<W>(),
        Builtin::Abs => builtin_fabs::<W>(value, optional), // abs is an alias for fabs
        Builtin::Builtins => builtin_builtins::<W>(),
        Builtin::Normals => builtin_normals::<W>(value),
        Builtin::Finites => builtin_finites::<W>(value),

        // Phase 13: Iteration control
        Builtin::Limit(n_expr, expr) => builtin_limit::<W, S>(n_expr, expr, value, optional),
        Builtin::FirstStream(expr) => builtin_first_stream::<W, S>(expr, value, optional),
        Builtin::LastStream(expr) => builtin_last_stream::<W, S>(expr, value, optional),
        Builtin::NthStream(n_expr, expr) => {
            builtin_nth_stream::<W, S>(n_expr, expr, value, optional)
        }
        Builtin::IsEmpty(expr) => builtin_isempty::<W, S>(expr, value, optional),

        // Phase 14: Recursive traversal (extends Phase 8)
        Builtin::RecurseDown => builtin_recurse::<W, S>(value, optional), // alias for recurse

        // Phase 15: Date/Time functions
        Builtin::Gmtime => builtin_gmtime::<W>(value, optional),
        Builtin::Localtime => builtin_localtime::<W>(value, optional),
        Builtin::Mktime => builtin_mktime::<W>(value, optional),
        Builtin::Strftime(fmt) => builtin_strftime::<W, S>(fmt, value, optional),
        Builtin::Strptime(fmt) => builtin_strptime::<W, S>(fmt, value, optional),
        Builtin::Todate => builtin_todate::<W>(value, optional),
        Builtin::Fromdate => builtin_fromdate::<W>(value, optional),
        Builtin::Todateiso8601 => builtin_todate::<W>(value, optional), // alias for todate
        Builtin::Fromdateiso8601 => builtin_fromdate::<W>(value, optional), // alias for fromdate

        // Phase 17: Combinations
        Builtin::Combinations => builtin_combinations::<W>(value, optional),
        Builtin::CombinationsN(n) => builtin_combinations_n::<W, S>(n, value, optional),

        // Phase 18: Additional math functions
        Builtin::Trunc => builtin_trunc::<W>(value, optional),

        // Phase 19: Type conversion
        Builtin::ToBoolean => builtin_toboolean::<W>(value, optional),

        // Phase 20: Iteration control extension
        Builtin::Skip(n_expr, expr) => builtin_skip::<W, S>(n_expr, expr, value, optional),

        // Phase 21: Extended Date/Time functions (yq)
        Builtin::FromUnix => builtin_from_unix::<W>(value, optional),
        Builtin::ToUnix => builtin_to_unix::<W>(value, optional),
        Builtin::Tz(zone) => builtin_tz::<W, S>(zone, value, optional),

        // Phase 22: File operations (yq)
        Builtin::Load(file_expr) => builtin_load::<W, S>(file_expr, value, optional),

        // Phase 23: Position-based navigation (succinctly extension)
        // These require cursor context - handled in eval_generic.rs
        Builtin::AtOffset(_) => QueryResult::Error(EvalError::new(
            "at_offset requires document cursor context".to_string(),
        )),
        Builtin::AtPosition(_, _) => QueryResult::Error(EvalError::new(
            "at_position requires document cursor context".to_string(),
        )),
    }
}

/// Builtin: length
fn builtin_length<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    match &value {
        StandardJson::Null => QueryResult::Owned(OwnedValue::Int(0)),
        StandardJson::String(s) => {
            if let Ok(cow) = s.as_str() {
                QueryResult::Owned(OwnedValue::Int(cow.chars().count() as i64))
            } else {
                QueryResult::Owned(OwnedValue::Int(0))
            }
        }
        StandardJson::Array(elements) => {
            QueryResult::Owned(OwnedValue::Int((*elements).count() as i64))
        }
        StandardJson::Object(fields) => {
            QueryResult::Owned(OwnedValue::Int((*fields).count() as i64))
        }
        StandardJson::Number(n) => {
            // Length of a number is its absolute value.
            // checked_abs: i64::MIN has no i64 absolute value; use f64
            if is_nan_sentinel(n.raw_bytes()) {
                QueryResult::Owned(OwnedValue::Float(f64::NAN))
            } else if let Ok(i) = n.as_i64() {
                QueryResult::Owned(match i.checked_abs() {
                    Some(a) => OwnedValue::Int(a),
                    None => OwnedValue::Float(-(i as f64)),
                })
            } else if let Ok(f) = n.as_f64() {
                QueryResult::Owned(OwnedValue::Float(f.abs()))
            } else {
                QueryResult::Owned(OwnedValue::Int(0))
            }
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::has_no_length(&to_owned(&value))),
    }
}

/// Builtin: utf8bytelength
fn builtin_utf8bytelength<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    match &value {
        StandardJson::String(s) => {
            if let Ok(cow) = s.as_str() {
                QueryResult::Owned(OwnedValue::Int(cow.len() as i64))
            } else {
                QueryResult::Owned(OwnedValue::Int(0))
            }
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::no_utf8_byte_length(&to_owned(&value))),
    }
}

/// Builtin: keys / keys_unsorted
fn builtin_keys<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
    sorted: bool,
) -> QueryResult<'_, W> {
    match value {
        StandardJson::Object(fields) => {
            let mut keys: Vec<String> = Vec::new();
            for field in fields {
                if let StandardJson::String(k) = field.key() {
                    if let Ok(cow) = k.as_str() {
                        keys.push(cow.into_owned());
                    }
                }
            }
            if sorted {
                keys.sort();
            }
            let arr: Vec<OwnedValue> = keys.into_iter().map(OwnedValue::String).collect();
            QueryResult::Owned(OwnedValue::Array(arr))
        }
        StandardJson::Array(elements) => {
            // For arrays, keys returns indices [0, 1, 2, ...]
            let len = elements.count();
            let arr: Vec<OwnedValue> = (0..len).map(|i| OwnedValue::Int(i as i64)).collect();
            QueryResult::Owned(OwnedValue::Array(arr))
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::has_no_keys(&to_owned(&value))),
    }
}

/// Builtin: has(key)
fn builtin_has<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    key_expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // Evaluate the key expression
    let key_result = eval_single::<W, S>(key_expr, value.clone(), optional);
    let key_owned = match result_to_owned(key_result) {
        Ok(v) => v,
        Err(e) => return e.into(),
    };

    match (&value, &key_owned) {
        // jq: null | has("key") => false
        (StandardJson::Null, _) => QueryResult::Owned(OwnedValue::Bool(false)),
        // Object has string key
        (StandardJson::Object(fields), OwnedValue::String(key)) => {
            let found = (*fields).clone().any(|f| {
                if let StandardJson::String(k) = f.key() {
                    if let Ok(cow) = k.as_str() {
                        return cow.as_ref() == key;
                    }
                }
                false
            });
            QueryResult::Owned(OwnedValue::Bool(found))
        }
        // Array has index - jq returns false for negative, yq returns true if in range
        (
            StandardJson::Array(elements),
            OwnedValue::Int(idx) | OwnedValue::NumberLiteral(NumberRepr::Int(idx), _),
        ) => {
            let len = (*elements).count() as i64;
            let in_bounds = if S::NEGATIVE_INDEX_IN_HAS {
                // yq behavior: negative indices are valid if abs(idx) <= len
                if *idx >= 0 {
                    *idx < len
                } else {
                    idx.abs() <= len
                }
            } else {
                // jq behavior: only non-negative indices
                *idx >= 0 && *idx < len
            };
            QueryResult::Owned(OwnedValue::Bool(in_bounds))
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::cannot_check_has(
            type_name(&value),
            key_owned.type_name(),
        )),
    }
}

/// Builtin: in(obj)
fn builtin_in<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    obj_expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // The input should be a key (string or number), and we check if it exists in obj
    let key_owned = to_owned(&value);
    let obj_result = eval_single::<W, S>(obj_expr, value.clone(), optional);

    // Get the object/array to check against (need to handle Owned case for object literals)
    let obj_owned = match obj_result {
        QueryResult::One(o) => to_owned(&o),
        QueryResult::Many(os) => {
            if let Some(o) = os.into_iter().next() {
                to_owned(&o)
            } else if optional {
                return QueryResult::None;
            } else {
                return QueryResult::Error(EvalError::new(
                    "in() requires an object or array argument",
                ));
            }
        }
        QueryResult::Owned(o) => o,
        QueryResult::Error(e) => return QueryResult::Error(e),
        _ if optional => return QueryResult::None,
        _ => {
            return QueryResult::Error(EvalError::new("in() requires an object or array argument"));
        }
    };

    match (&key_owned, &obj_owned) {
        (OwnedValue::String(key), OwnedValue::Object(fields)) => {
            let found = fields.keys().any(|k| k == key);
            QueryResult::Owned(OwnedValue::Bool(found))
        }
        // jq returns false for negative indices, yq returns true if in range
        (
            OwnedValue::Int(idx) | OwnedValue::NumberLiteral(NumberRepr::Int(idx), _),
            OwnedValue::Array(elements),
        ) => {
            let len = elements.len() as i64;
            let in_bounds = if S::NEGATIVE_INDEX_IN_HAS {
                // yq behavior: negative indices are valid if abs(idx) <= len
                if *idx >= 0 {
                    *idx < len
                } else {
                    idx.abs() <= len
                }
            } else {
                // jq behavior: only non-negative indices
                *idx >= 0 && *idx < len
            };
            QueryResult::Owned(OwnedValue::Bool(in_bounds))
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::cannot_check_has(
            obj_owned.type_name(),
            key_owned.type_name(),
        )),
    }
}

/// Builtin: `IN(s)` - true if any output of `s` (run against the current
/// value) equals the current value. Matches jq's `any(s == .; .)`.
fn builtin_upper_in<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    s: &Expr,
    value: StandardJson<'a, W>,
    _optional: bool,
) -> QueryResult<'a, W> {
    let current = to_owned(&value);
    let candidates = match eval_owned_multi::<S>(s, &current) {
        Ok(c) => c,
        Err(e) => return e.into(),
    };
    QueryResult::Owned(OwnedValue::Bool(candidates.contains(&current)))
}

/// Builtin: `IN(src; s)` - true if any output of `src` equals any output of
/// `s`, both run independently against the current value.
///
/// Note: this is *not* a literal translation of upstream's documented
/// `def IN(src; s): any(src|s == .; .);` — that def's `.` inside `s == .`
/// gets rebound by the `src|` pipe before `s` ever runs, so it can never see
/// the original current value and (verified against real jq 1.7.1) does not
/// reproduce the oracle's actual output. The cartesian-equality form here
/// (`any(src == s; .)`) was verified to match the real builtin's behavior
/// across a battery of cases (see issue #722).
fn builtin_upper_in_src<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    src: &Expr,
    s: &Expr,
    value: StandardJson<'a, W>,
    _optional: bool,
) -> QueryResult<'a, W> {
    let current = to_owned(&value);
    let haystack = match eval_owned_multi::<S>(src, &current) {
        Ok(v) => v,
        Err(e) => return e.into(),
    };
    let needles = match eval_owned_multi::<S>(s, &current) {
        Ok(v) => v,
        Err(e) => return e.into(),
    };
    let found = haystack.iter().any(|h| needles.iter().any(|n| n == h));
    QueryResult::Owned(OwnedValue::Bool(found))
}

/// Builtin: select(condition)
///
/// A multi-output condition republishes `value` once per truthy output
/// (`select((false,false) and true)` yields nothing, matching jq — not the
/// first-output-only answer `vs.first()` used to give) — restored by
/// `eval_fanout` (#378).
fn builtin_select<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    cond: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    let cond_result = eval_single::<W, S>(cond, value.clone(), optional);
    eval_fanout(cond_result, |truthy| {
        if truthy {
            QueryResult::One(value.clone())
        } else {
            QueryResult::None
        }
    })
}

/// Builtin: map(f)
/// Applies `f` to each element and materializes the results into a flat
/// array — the shared body of `map(f)`, over either an array's elements or
/// an object's values.
fn map_over<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    f: &Expr,
    elements: impl Iterator<Item = StandardJson<'a, W>>,
    optional: bool,
) -> QueryResult<'a, W> {
    let mut results = Vec::new();
    for elem in elements {
        match eval_single::<W, S>(f, elem, optional).materialize_cursor() {
            QueryResult::One(v) => results.push(to_owned(&v)),
            QueryResult::OneCursor(_) => unreachable!(),
            QueryResult::Owned(v) => results.push(v),
            QueryResult::Many(vs) => results.extend(vs.iter().map(to_owned)),
            QueryResult::ManyOwned(vs) => results.extend(vs),
            QueryResult::None => {}
            QueryResult::Error(e) => return QueryResult::Error(e),
            QueryResult::Break(label) => return QueryResult::Break(label),
            QueryResult::Halt(code) => return QueryResult::Halt(code),
            // `map(f)` is `[.[] | f]` — array construction, atomic in jq
            // (see `eval_array_construction`) — so a `Partial` just
            // surfaces its control, same as a bare one.
            QueryResult::Partial(_, Control::Error(e)) => return QueryResult::Error(e),
            QueryResult::Partial(_, Control::Break(label)) => return QueryResult::Break(label),
            QueryResult::Partial(_, Control::Halt(code)) => return QueryResult::Halt(code),
        }
    }
    QueryResult::Owned(OwnedValue::Array(results))
}

fn builtin_map<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    f: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // map(f) is [.[] | f], and .[] over an object iterates its values, so jq
    // accepts an object here as readily as an array (#422).
    match value {
        StandardJson::Array(elements) => map_over::<W, S>(f, elements, optional),
        StandardJson::Object(fields) => {
            map_over::<W, S>(f, fields.map(|fld| fld.value()), optional)
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::cannot_iterate(&to_owned(&value))),
    }
}

/// Builtin: map_values(f)
fn builtin_map_values<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    f: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    match value {
        StandardJson::Object(fields) => {
            let mut result_map = IndexMap::new();
            for field in fields {
                // Get the key
                let key = if let StandardJson::String(k) = field.key() {
                    if let Ok(cow) = k.as_str() {
                        cow.into_owned()
                    } else {
                        continue;
                    }
                } else {
                    continue;
                };

                // Apply f to the value
                let field_val = field.value();
                match eval_single::<W, S>(f, field_val, optional).materialize_cursor() {
                    QueryResult::One(v) => {
                        result_map.insert(key, to_owned(&v));
                    }
                    QueryResult::OneCursor(_) => unreachable!(),
                    QueryResult::Owned(v) => {
                        result_map.insert(key, v);
                    }
                    QueryResult::Many(vs) => {
                        if let Some(v) = vs.first() {
                            result_map.insert(key, to_owned(v));
                        }
                    }
                    QueryResult::ManyOwned(vs) => {
                        if let Some(v) = vs.into_iter().next() {
                            result_map.insert(key, v);
                        }
                    }
                    QueryResult::None => {}
                    QueryResult::Error(e) => return QueryResult::Error(e),
                    QueryResult::Break(label) => return QueryResult::Break(label),
                    QueryResult::Halt(code) => return QueryResult::Halt(code),
                    // Object construction is atomic in jq (see
                    // `eval_object_construction`) — a `Partial` field value
                    // just surfaces its control, same as a bare one.
                    QueryResult::Partial(_, Control::Error(e)) => return QueryResult::Error(e),
                    QueryResult::Partial(_, Control::Break(label)) => {
                        return QueryResult::Break(label);
                    }
                    QueryResult::Partial(_, Control::Halt(code)) => {
                        return QueryResult::Halt(code);
                    }
                }
            }
            QueryResult::Owned(OwnedValue::Object(result_map))
        }
        StandardJson::Array(elements) => {
            // map_values on array applies to each element
            let mut results = Vec::new();
            for elem in elements {
                match eval_single::<W, S>(f, elem, optional).materialize_cursor() {
                    QueryResult::One(v) => results.push(to_owned(&v)),
                    QueryResult::OneCursor(_) => unreachable!(),
                    QueryResult::Owned(v) => results.push(v),
                    QueryResult::Many(vs) => {
                        if let Some(v) = vs.first() {
                            results.push(to_owned(v));
                        }
                    }
                    QueryResult::ManyOwned(vs) => {
                        if let Some(v) = vs.into_iter().next() {
                            results.push(v);
                        }
                    }
                    QueryResult::None => {}
                    QueryResult::Error(e) => return QueryResult::Error(e),
                    QueryResult::Break(label) => return QueryResult::Break(label),
                    QueryResult::Halt(code) => return QueryResult::Halt(code),
                    // Array construction is atomic in jq — a `Partial`
                    // element value just surfaces its control, same as a
                    // bare one.
                    QueryResult::Partial(_, Control::Error(e)) => return QueryResult::Error(e),
                    QueryResult::Partial(_, Control::Break(label)) => {
                        return QueryResult::Break(label);
                    }
                    QueryResult::Partial(_, Control::Halt(code)) => {
                        return QueryResult::Halt(code);
                    }
                }
            }
            QueryResult::Owned(OwnedValue::Array(results))
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::type_error("object or array", type_name(&value))),
    }
}

/// Builtin: add
fn builtin_add<W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    // add is [.[] | .] folded with +, and .[] over an object iterates its
    // values, so jq accepts an object here as readily as an array (#422).
    let items: Vec<OwnedValue> = match value {
        StandardJson::Array(elements) => elements.map(|e| to_owned(&e)).collect(),
        StandardJson::Object(fields) => fields.map(|f| to_owned(&f.value())).collect(),
        _ if optional => return QueryResult::None,
        _ => return QueryResult::Error(EvalError::cannot_iterate(&to_owned(&value))),
    };
    if items.is_empty() {
        return QueryResult::Owned(OwnedValue::Null);
    }

    // Fold the items using addition
    let mut acc = items.into_iter();
    let first = acc.next().unwrap();
    let result = acc.try_fold(first, arith_add::<S>);

    match result {
        Ok(v) => QueryResult::Owned(v),
        Err(e) => e.into(),
    }
}

/// Short-circuiting fold shared by `any`/`all`: returns `target_truthy` as
/// soon as an element's truthiness matches it, instead of walking the rest
/// of the container. `any` looks for a truthy element (`target_truthy =
/// true`); `all` looks for a falsy one (`target_truthy = false`).
fn any_all_over<'a, W: Clone + AsRef<[u64]> + 'a>(
    elements: impl Iterator<Item = StandardJson<'a, W>>,
    target_truthy: bool,
) -> bool {
    for elem in elements {
        if to_owned(&elem).is_truthy() == target_truthy {
            return target_truthy;
        }
    }
    !target_truthy
}

/// Builtin: any
///
/// any is [.[] | .] with an early-exit truthiness check, and .[] over an
/// object iterates its values, so jq accepts an object here as readily as
/// an array (#422).
fn builtin_any<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    match value {
        StandardJson::Array(elements) => {
            QueryResult::Owned(OwnedValue::Bool(any_all_over(elements, true)))
        }
        StandardJson::Object(fields) => QueryResult::Owned(OwnedValue::Bool(any_all_over(
            fields.map(|f| f.value()),
            true,
        ))),
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::cannot_iterate(&to_owned(&value))),
    }
}

/// Builtin: all
///
/// Same shape as `any` — see #422.
fn builtin_all<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    match value {
        StandardJson::Array(elements) => {
            QueryResult::Owned(OwnedValue::Bool(any_all_over(elements, false)))
        }
        StandardJson::Object(fields) => QueryResult::Owned(OwnedValue::Bool(any_all_over(
            fields.map(|f| f.value()),
            false,
        ))),
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::cannot_iterate(&to_owned(&value))),
    }
}

/// Probes a single element's `cond` output for a match, using the same
/// prefix-vs-trailing-control split as `eval_limit`/`eval_first_expr`
/// (`eval_owned_expr_fork`), so a match found before a later error in the
/// same `cond` application still short-circuits instead of surfacing that
/// error — jq's own `first(...)`-based definitions only pull one output at
/// a time, so `cond` yielding `(false, error(...))` for one element must
/// resolve on the `false` alone.
fn any_all_probe_element<S: EvalSemantics>(
    cond: &Expr,
    elem: &OwnedValue,
    target_truthy: bool,
) -> Result<bool, Control> {
    let (cond_outputs, cond_trailing) = eval_owned_expr_fork::<S>(cond, elem, false);
    if cond_outputs.iter().any(|c| c.is_truthy() == target_truthy) {
        return Ok(true);
    }
    match cond_trailing {
        Some(control) => Err(control),
        None => Ok(false),
    }
}

fn control_to_result<'a, W: Clone + AsRef<[u64]>>(control: Control) -> QueryResult<'a, W> {
    match control {
        Control::Error(e) => QueryResult::Error(e),
        Control::Break(label) => QueryResult::Break(label),
        Control::Halt(code) => QueryResult::Halt(code),
    }
}

/// Shared engine for `any(cond)`/`all(cond)`: iterates the container's own
/// elements (array items or object values — matching bare `any`/`all`'s
/// #422 object support), applying `cond` per element with
/// short-circuit-on-match semantics.
fn any_all_f<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    cond: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
    target_truthy: bool,
) -> QueryResult<'a, W> {
    let elements: Vec<OwnedValue> = match value {
        StandardJson::Array(elements) => elements.map(|e| to_owned(&e)).collect(),
        StandardJson::Object(fields) => fields.map(|f| to_owned(&f.value())).collect(),
        _ if optional => return QueryResult::None,
        _ => return QueryResult::Error(EvalError::cannot_iterate(&to_owned(&value))),
    };
    for elem in &elements {
        match any_all_probe_element::<S>(cond, elem, target_truthy) {
            Ok(true) => return QueryResult::Owned(OwnedValue::Bool(target_truthy)),
            Ok(false) => {}
            Err(control) => return control_to_result(control),
        }
    }
    QueryResult::Owned(OwnedValue::Bool(!target_truthy))
}

/// Builtin: `any(cond)` - true if cond is truthy for any element of `.[]`.
fn builtin_any_f<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    cond: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    any_all_f::<W, S>(cond, value, optional, true)
}

/// Builtin: `all(cond)` - true if cond is truthy for every element of `.[]`.
fn builtin_all_f<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    cond: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    any_all_f::<W, S>(cond, value, optional, false)
}

/// Shared engine for `any(gen; cond)`/`all(gen; cond)`, matching real jq's
/// `isempty(generator|condition {and,or} empty)`-based definitions: a
/// match found among `gen`'s outputs short-circuits and drops any later
/// error/break from the unexamined remainder of `gen`.
fn any_all_gen_cond<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    gen: &Expr,
    cond: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
    target_truthy: bool,
) -> QueryResult<'a, W> {
    let owned = to_owned(&value);
    let (gen_outputs, gen_trailing) = eval_owned_expr_fork::<S>(gen, &owned, optional);
    for elem in &gen_outputs {
        match any_all_probe_element::<S>(cond, elem, target_truthy) {
            Ok(true) => return QueryResult::Owned(OwnedValue::Bool(target_truthy)),
            Ok(false) => {}
            Err(control) => return control_to_result(control),
        }
    }
    match gen_trailing {
        Some(control) => control_to_result(control),
        None => QueryResult::Owned(OwnedValue::Bool(!target_truthy)),
    }
}

/// Builtin: `any(gen; cond)` - true if cond is truthy for any output of gen.
fn builtin_any_cond<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    gen: &Expr,
    cond: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    any_all_gen_cond::<W, S>(gen, cond, value, optional, true)
}

/// Builtin: `all(gen; cond)` - true if cond is truthy for every output of gen.
fn builtin_all_cond<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    gen: &Expr,
    cond: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    any_all_gen_cond::<W, S>(gen, cond, value, optional, false)
}

/// Builtin: min
fn builtin_min<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    match value {
        StandardJson::Array(elements) => {
            let items: Vec<OwnedValue> = elements.map(|e| to_owned(&e)).collect();
            if items.is_empty() {
                return QueryResult::Owned(OwnedValue::Null);
            }

            let min = items.into_iter().min_by(compare_values).unwrap();
            QueryResult::Owned(min)
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::pair_cannot_be_iterated(
            &to_owned(&value),
            &to_owned(&value),
        )),
    }
}

/// Builtin: max
fn builtin_max<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    match value {
        StandardJson::Array(elements) => {
            let items: Vec<OwnedValue> = elements.map(|e| to_owned(&e)).collect();
            if items.is_empty() {
                return QueryResult::Owned(OwnedValue::Null);
            }

            let max = items.into_iter().max_by(compare_values).unwrap();
            QueryResult::Owned(max)
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::pair_cannot_be_iterated(
            &to_owned(&value),
            &to_owned(&value),
        )),
    }
}

/// Builtin: min_by(f)
fn builtin_min_by<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    f: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    match value {
        StandardJson::Array(elements) => {
            let items: Vec<StandardJson<'a, W>> = elements.collect();
            if items.is_empty() {
                return QueryResult::Owned(OwnedValue::Null);
            }

            // Compute keys for each item. jq keys by `[f]` — the array of
            // *all* outputs of the key filter, not just its first output
            // (#155).
            let mut keyed: Vec<(OwnedValue, StandardJson<'a, W>)> = Vec::new();
            for item in items {
                match eval_array_construction::<W, S>(f, item.clone(), optional) {
                    QueryResult::Owned(v) => keyed.push((v, item)),
                    QueryResult::Error(e) => return QueryResult::Error(e),
                    QueryResult::Break(label) => return QueryResult::Break(label),
                    QueryResult::Halt(code) => return QueryResult::Halt(code),
                    _ => {
                        unreachable!("eval_array_construction only returns Owned/Error/Break/Halt")
                    }
                }
            }

            let min = keyed
                .into_iter()
                .min_by(|(a, _), (b, _)| compare_values(a, b))
                .map(|(_, v)| to_owned(&v))
                .unwrap();
            QueryResult::Owned(min)
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::type_error("array", type_name(&value))),
    }
}

/// Builtin: max_by(f)
fn builtin_max_by<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    f: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    match value {
        StandardJson::Array(elements) => {
            let items: Vec<StandardJson<'a, W>> = elements.collect();
            if items.is_empty() {
                return QueryResult::Owned(OwnedValue::Null);
            }

            // Compute keys for each item. jq keys by `[f]` — the array of
            // *all* outputs of the key filter, not just its first output
            // (#155).
            let mut keyed: Vec<(OwnedValue, StandardJson<'a, W>)> = Vec::new();
            for item in items {
                match eval_array_construction::<W, S>(f, item.clone(), optional) {
                    QueryResult::Owned(v) => keyed.push((v, item)),
                    QueryResult::Error(e) => return QueryResult::Error(e),
                    QueryResult::Break(label) => return QueryResult::Break(label),
                    QueryResult::Halt(code) => return QueryResult::Halt(code),
                    _ => {
                        unreachable!("eval_array_construction only returns Owned/Error/Break/Halt")
                    }
                }
            }

            let max = keyed
                .into_iter()
                .max_by(|(a, _), (b, _)| compare_values(a, b))
                .map(|(_, v)| to_owned(&v))
                .unwrap();
            QueryResult::Owned(max)
        }
        _ if optional => QueryResult::None,
        _ => QueryResult::Error(EvalError::type_error("array", type_name(&value))),
    }
}

