    #[test]
    fn test_variable_binding_as() {
        // Simple variable binding: .foo as $x | .bar + $x
        query!(br#"{"foo": 10, "bar": 5}"#, r".foo as $x | .bar + $x",
            QueryResult::Owned(OwnedValue::Int(15)) => {}
        );

        // Variable with object construction
        query!(br#"{"name": "Alice", "age": 30}"#, r#".name as $n | {name: $n, greeting: "Hello"}"#,
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(obj.get("name"), Some(&OwnedValue::String("Alice".to_string())));
                assert_eq!(obj.get("greeting"), Some(&OwnedValue::String("Hello".to_string())));
            }
        );
    }

    #[test]
    fn test_variable_binding_preserves_streaming_through_a_multi_output_filter() {
        // A pipe stage after `as` binds a value is still a pipe: piping a
        // bound variable into a multi-output filter must keep streaming N
        // separate top-level outputs, the same as piping the document
        // itself would. `$doc | paths` used to collapse into one array
        // (`eval_owned_pipe` collapsed through `eval_owned_expr`, which is
        // correct for `reduce`/`foreach` but not for a plain pipe
        // continuation) where `paths` alone streams correctly.
        assert_eq!(
            outputs(br#"{"a":{"b":1}}"#, ". as $doc | $doc | paths"),
            outputs(br#"{"a":{"b":1}}"#, "paths")
        );
        assert_eq!(
            outputs(br#"{"a":{"b":1}}"#, ". as $doc | $doc | paths"),
            [r#"["a"]"#, r#"["a","b"]"#]
        );
    }

    #[test]
    fn test_reduce() {
        // Sum array elements
        query!(br"[1, 2, 3, 4, 5]", r"reduce .[] as $x (0; . + $x)",
            QueryResult::Owned(OwnedValue::Int(15)) => {}
        );

        // Count elements
        query!(br#"["a", "b", "c"]"#, r"reduce .[] as $x (0; . + 1)",
            QueryResult::Owned(OwnedValue::Int(3)) => {}
        );
    }

    #[test]
    fn test_foreach() {
        // Running sum
        query!(br"[1, 2, 3]", r"[foreach .[] as $x (0; . + $x)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
                assert_eq!(arr[0], OwnedValue::Int(1));
                assert_eq!(arr[1], OwnedValue::Int(3));
                assert_eq!(arr[2], OwnedValue::Int(6));
            }
        );
    }

    /// `reduce`'s INIT/UPDATE slots now accept a top-level comma (#534): the
    /// parser previously rejected these outright, so this pins the
    /// evaluator's actual fanout/fold behavior now that it's reachable.
    #[test]
    fn test_reduce_comma_slots() {
        // UPDATE-comma: only the last output of each step becomes the next
        // accumulator (verified against jq 1.7.1: `0`).
        assert_eq!(outputs(b"[1,2,3]", "reduce .[] as $x (0; .+$x, .)"), ["0"]);

        // INIT-comma: each INIT output independently forks the whole
        // reduce, re-running over the *same* source stream. Real jq 1.7.1
        // diverges here for a reason unrelated to this evaluator: its own
        // bytecode re-enters `SOURCE` on the second INIT fork with `.`
        // already clobbered by the first fork's own iteration (`jq -n
        // 'reduce .[] as $x (0,1; .+$x)' <<<'[1,2,3]'` prints `6` then
        // errors "Cannot iterate over null"). This codebase's INIT-forking
        // doesn't share that quirk — pinning succinctly's own consistent
        // value here, not jq's, so a future refactor doesn't silently
        // change it either way without a failing test to flag it.
        assert_eq!(
            outputs(b"[1,2,3]", "reduce .[] as $x (0,1; .+$x)"),
            ["6", "7"]
        );
    }

    /// `foreach`'s INIT/UPDATE/EXTRACT slots now accept a top-level comma
    /// (#534) — same parser widening as `reduce` above.
    #[test]
    fn test_foreach_comma_slots() {
        // UPDATE-comma, no EXTRACT: every UPDATE output is emitted (not
        // folded), and the *last* one carries forward as the next state
        // (verified against jq 1.7.1: `1,0,2,0,3,0`).
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (0; .+$x, .)"),
            ["1", "0", "2", "0", "3", "0"]
        );

        // EXTRACT-comma: EXTRACT's own outputs fan out per step (verified
        // against jq 1.7.1: `1,2,3,6,6,12`).
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (0; .+$x; ., .*2)"),
            ["1", "2", "3", "6", "6", "12"]
        );

        // INIT-comma: same jq-engine-quirk divergence as `reduce` above
        // (jq prints `1,3,6` then errors; pinning succinctly's own value).
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (0,1; .+$x)"),
            ["1", "3", "6", "2", "4", "7"]
        );
    }

    #[test]
    fn test_range() {
        // range(n) - generates 0 to n-1
        query!(br"null", r"[range(5)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(0),
                    OwnedValue::Int(1),
                    OwnedValue::Int(2),
                    OwnedValue::Int(3),
                    OwnedValue::Int(4),
                ]);
            }
        );

        // range(a;b) - generates a to b-1
        query!(br"null", r"[range(2;5)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(2),
                    OwnedValue::Int(3),
                    OwnedValue::Int(4),
                ]);
            }
        );

        // range(a;b;step)
        query!(br"null", r"[range(0;10;2)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(0),
                    OwnedValue::Int(2),
                    OwnedValue::Int(4),
                    OwnedValue::Int(6),
                    OwnedValue::Int(8),
                ]);
            }
        );
    }

    #[test]
    fn test_limit() {
        // limit(n; expr) - take first n outputs
        query!(br"null", r"[limit(3; range(10))]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(0),
                    OwnedValue::Int(1),
                    OwnedValue::Int(2),
                ]);
            }
        );
    }

    /// `limit`'s `expr` argument now accepts a top-level comma-generator
    /// (#155): `[limit(2;1,2,3,4)]` == `[1,2]`, matching real jq. The
    /// generator here is finite, so the existing eager
    /// evaluate-then-`take(n)` implementation already produces the correct
    /// answer without needing true short-circuiting.
    #[test]
    fn test_limit_comma_generator_argument() {
        query!(br"null", r"[limit(2;1,2,3,4)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![OwnedValue::Int(1), OwnedValue::Int(2)]);
            }
        );
    }

    #[test]
    fn test_first_last_expr() {
        // first(expr) - returns a reference to first element
        query!(br"[1, 2, 3]", r"first(.[])",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 1);
            }
        );

        // last(expr) - returns a reference to last element
        query!(br"[1, 2, 3]", r"last(.[])",
            QueryResult::One(StandardJson::Number(n)) => {
                assert_eq!(n.as_i64().unwrap(), 3);
            }
        );
    }

    /// `first`/`last`'s argument now accepts a top-level comma-generator
    /// (#155): `first(1,2,3)` == `1`, `last(1,2,3)` == `3`.
    #[test]
    fn test_first_last_expr_comma_generator_argument() {
        query!(br"null", r"first(1,2,3)",
            QueryResult::Owned(OwnedValue::Int(n)) => {
                assert_eq!(n, 1);
            }
        );

        query!(br"null", r"last(1,2,3)",
            QueryResult::Owned(OwnedValue::Int(n)) => {
                assert_eq!(n, 3);
            }
        );
    }

    /// A single-parameter user-defined function called with a
    /// comma-generator argument (#155): `def f(x): x; f(1,2)` fans out to
    /// two outputs, matching real jq's call-by-name substitution semantics.
    #[test]
    fn test_user_function_call_with_comma_generator_argument() {
        assert_eq!(
            outputs(b"null", "def f(x): x; f(1,2)"),
            vec!["1".to_string(), "2".to_string()]
        );
    }

    #[test]
    fn test_until() {
        // until(cond; update) - iterate until condition is true
        query!(br"1", r"until(. >= 10; . * 2)",
            QueryResult::Owned(OwnedValue::Int(16)) => {}
        );
    }

    #[test]
    fn test_while() {
        // while(cond; update) - output while condition is true
        query!(br"1", r"[while(. < 10; . * 2)]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(1),
                    OwnedValue::Int(2),
                    OwnedValue::Int(4),
                    OwnedValue::Int(8),
                ]);
            }
        );
    }

    /// `until`'s COND/UPDATE slots now accept a top-level comma (#534) —
    /// each additional `cond`/`update` output forks the rest of the
    /// backtracking search, verified against jq 1.7.1.
    #[test]
    fn test_until_comma_slots() {
        // UPDATE-comma: a 2-output UPDATE forks the remaining search once
        // per output (verified against jq 1.7.1: `1,10`).
        assert_eq!(outputs(b"0", "until(.>=1; .+1,.+10)"), ["1", "10"]);

        // COND-comma: a 2-output COND runs each output as its own
        // independent branch against the same state — both are truthy at
        // every state visited here, and each duplicates the branches below
        // it, so the final state (`1`) is emitted 4 times (verified against
        // jq 1.7.1).
        assert_eq!(
            outputs(b"0", "until((.>=1,.>=1); .+1)"),
            ["1", "1", "1", "1"]
        );
    }

    // The #534/#692 fork-control rewrite added several branches — INIT/INPUT
    // materialization arms in `eval_reduce`/`eval_foreach`, `eval_owned_expr_fork`,
    // `finish_fork`, and the `until_step`/`while_step` budget cap and forking-branch
    // control propagation — that the golden-file suite exercises (they run the CLI
    // binary as a subprocess, invisible to `cargo llvm-cov`'s instrumentation) but no
    // in-process unit test reaches. These pin the exact same scenarios directly
    // through `eval()` so they count.
    //
    // `$nope` (an unresolved variable) is the key to several of these: unlike
    // `error(...)`/arithmetic/type errors, `Expr::Var`'s undefined-variable arm
    // doesn't consult the ambient `optional` flag, so it's one of the few ways to
    // get a genuine `QueryResult::Error` out of `eval_single` while `optional` is
    // still `true` — everything else this codebase raises checks `optional` at its
    // own raise site and resolves straight to `None` instead (#693/#694 track this
    // ambient-`optional` architecture more broadly).

    #[test]
    fn test_reduce_update_empty_step_yields_unbound_null() {
        // `eval_owned_expr_fork`'s `QueryResult::None` arm: a zero-output UPDATE
        // step leaves the accumulator unbound, read back as `null` on the next
        // step (same scenario as the `reduce_update_unbound_null` golden case).
        assert_eq!(
            outputs(
                b"null",
                "reduce (1,2) as $x (0; if $x==2 then empty else .+$x end)"
            ),
            ["null"]
        );
    }

    #[test]
    fn eval_owned_expr_fork_empty_update_yields_no_outputs_directly() {
        let expr = parse("empty").unwrap();
        let (vals, control) = eval_owned_expr_fork::<JqSemantics>(&expr, &OwnedValue::Null, false);
        assert_eq!(vals, Vec::<OwnedValue>::new());
        assert!(control.is_none());
    }

    #[test]
    fn test_reduce_optional_swallows_update_error() {
        // `finish_fork`'s `Some(Control::Error(_)) if optional` arm: the UPDATE
        // step errors via `$nope`, and the whole `reduce` being wrapped in `?`
        // swallows it rather than letting it escape.
        assert_eq!(
            outputs(b"[1,2,3]", "(reduce .[] as $x (0; $nope))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_many_borrowed_refs() {
        // INIT `(.a,.b)` resolves to two borrowed document refs — exercises the
        // `QueryResult::Many` (not `ManyOwned`) arm of INIT materialization.
        assert_eq!(
            outputs(br#"{"a":1,"b":2}"#, "reduce range(2) as $x ((.a,.b); .+$x)"),
            ["2", "3"]
        );
    }

    #[test]
    fn test_reduce_init_empty_yields_no_output() {
        // Zero INIT outputs fork zero times, so the whole reduce produces
        // nothing at all.
        assert_eq!(
            outputs(b"[1,2,3]", "reduce .[] as $x (empty; .+$x)"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_error_swallowed_when_optional() {
        assert_eq!(
            outputs(b"[1,2,3]", "(reduce .[] as $x ($nope; .+$x))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_error_propagates() {
        query!(b"[1,2,3]", r"reduce .[] as $x ($nope; .+$x)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    #[test]
    fn test_reduce_init_break_propagates() {
        // A bare (non-`Partial`) `Break` out of INIT propagates directly out of
        // `reduce`, caught here by the enclosing `label`.
        assert_eq!(
            outputs(
                b"[1,2,3]",
                "label $lbl | reduce .[] as $x (break $lbl; .+$x)"
            ),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_reduce_init_partial_error_still_runs_the_fork_from_its_prefix_value() {
        // Corrected by #693 (was asserted the other way, unverified — see
        // below): INIT `(1,$nope)` produces `Partial([1], Control::Error(_))`
        // — under `?` only the trailing error is swallowed; the `1` INIT
        // already validly produced still forks and runs to completion,
        // matching this codebase's own "outputs already produced don't
        // vanish" contract (`partial()`/`prepend()`/`finish_fork`'s doc
        // comments) and jq's actual behavior. `$nope` (an undefined
        // variable) is a *compile*-time error in real jq, so it can't be
        // run directly there to check; re-verified the identical shape with
        // a *runtime* error instead immediately before writing this
        // assertion: `jq -n '[1,2,3] | (reduce .[] as $x ((1,error("boom"));
        // .+$x))?'` prints `7` — i.e. the fork from INIT's `1` runs
        // `1+1=2, 2+2=4, 4+3=7` to completion, exactly like this test now
        // expects. This test previously asserted the whole prefix was
        // discarded — an assumption that went unverified because, pre-#693,
        // this codebase's `Expr::Optional` self-suppressed every leaf error
        // it wrapped (including `$nope`'s—see the `$nope` explainer above),
        // so the (wrong) expectation and the (buggy) implementation
        // happened to agree.
        assert_eq!(
            outputs(b"[1,2,3]", "(reduce .[] as $x ((1,$nope); .+$x))?"),
            ["7"]
        );
    }

    #[test]
    fn test_reduce_init_partial_break_keeps_prefix() {
        // INIT `(1, break $lbl)` produces `Partial([1], Control::Break(_))` —
        // the fallback arm keeps the prefix (`1`) as the one INIT fork, and the
        // trailing break is caught by the enclosing label after that fork runs.
        assert_eq!(
            outputs(
                b"[1,2,3]",
                "label $lbl | reduce .[] as $x ((1, break $lbl); .+$x)"
            ),
            ["7"]
        );
    }

    #[test]
    fn test_foreach_input_error_swallowed_when_optional() {
        // Mirrors `eval_reduce`'s equivalent guard on the INPUT stream: an
        // immediate (non-`Partial`) error there has no prefix to salvage, so
        // `?` suppresses it.
        assert_eq!(
            outputs(b"null", "(foreach ($nope) as $x (0; .+$x))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_foreach_init_many_borrowed_refs() {
        assert_eq!(
            outputs(
                br#"{"a":1,"b":2}"#,
                "foreach range(2) as $x ((.a,.b); .+$x)"
            ),
            ["1", "2", "2", "3"]
        );
    }

    #[test]
    fn test_foreach_init_empty_yields_no_output() {
        assert_eq!(
            outputs(b"[1,2,3]", "foreach .[] as $x (empty; .+$x)"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_foreach_init_error_swallowed_when_optional() {
        assert_eq!(
            outputs(b"[1,2,3]", "(foreach .[] as $x ($nope; .+$x))?"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_foreach_init_error_propagates() {
        query!(b"[1,2,3]", r"foreach .[] as $x ($nope; .+$x)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    #[test]
    fn test_foreach_init_break_propagates() {
        assert_eq!(
            outputs(
                b"[1,2,3]",
                "label $lbl | foreach .[] as $x (break $lbl; .+$x)"
            ),
            Vec::<String>::new()
        );
    }

    // #693: `$nope` (above) is the *one* leaf that never self-suppressed via
    // the old ambient-`optional` bug, so the tests above never actually
    // exercised the failure mode from the issue — a `?`-wrapped fork
    // construct whose UPDATE/COND step raises via `error(...)` (the
    // realistic case). These pin that directly, against pinned `jq 1.7.1`
    // output.

    #[test]
    fn test_693_reduce_update_error_swallowed_by_optional() {
        // Before the fix: UPDATE's `error("boom")` self-suppressed to `None`
        // at the leaf (ambient `optional = true`), so `eval_reduce` never saw
        // an `Error`/`Partial` to abort on, and `.` (the unbound accumulator)
        // read back as `null` — `(reduce (1) as $x (0; error("boom")))?`
        // wrongly produced `null` instead of stopping with no output.
        assert_eq!(
            outputs(b"null", r#"(reduce (1) as $x (0; error("boom")))?"#),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_693_foreach_update_error_aborts_every_fork_not_just_the_current_one() {
        // Multi-output INIT `(10,20)` forks foreach over two accumulators.
        // Before the fix, fork 1's masked error "recovered" to a bound
        // `null` instead of aborting, and fork 2 — which real jq's `?` never
        // attempts once fork 1 errors — ran anyway, wrongly producing
        // `[2,21,23]`.
        assert_eq!(
            outputs(
                b"null",
                r#"(foreach (1,2) as $x ((10,20); if .==10 then error("boom") else .+$x end))?"#
            ),
            Vec::<String>::new()
        );
    }

    #[test]
    fn test_693_while_stops_at_the_masked_error_instead_of_burning_the_step_budget() {
        // Before the fix, the masked error inside `while`'s UPDATE never
        // reached `until_step`/`while_step`'s abort check, so the loop spun
        // through `0..12` repeatedly until `WHILE_UNTIL_MAX_STEPS` tripped.
        assert_eq!(
            outputs(
                b"null",
                "(10|while(. < 30; if . == 12 then error(\"boom\"), 0 else .+1 end))?"
            ),
            ["10", "11", "12"]
        );
    }

    #[test]
    fn test_693_optional_around_a_fork_construct_also_catches_an_escaping_break() {
        // `finish_fork` deliberately never special-cases `Break` (see its doc
        // comment) — catching one is the wrapping `?`/`try` boundary's job.
        // Before this fix, `Expr::Optional`'s dispatch had no such boundary
        // logic, so the `break $out` inside the `reduce` escaped straight
        // past the `?` and was caught by `label $out` one step too early,
        // wrongly producing `[1]` instead of jq's `[1,4]`.
        assert_eq!(
            outputs(
                b"null",
                "label $out | (1, (reduce (1,2) as $x (0; break $out))?, 4)"
            ),
            ["1", "4"]
        );
    }

    #[test]
    fn test_reduce_budget_exceeded_errors() {
        // 10001 UPDATE evals against a single INIT fork exceeds
        // REDUCE_FOREACH_MAX_STEPS; `reduce` only pushes output after its
        // fold completes, so no output survives to make this a `Partial`.
        query!(b"null", r"reduce range(10001) as $x (0; .+$x)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("reduce: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_foreach_budget_exceeded_errors() {
        // No EXTRACT, so only the per-input-element UPDATE charge fires;
        // outputs already produced survive as the `Partial` prefix.
        query!(b"null", r"foreach range(20000) as $x (0; .+1)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix.len(), REDUCE_FOREACH_MAX_STEPS);
                assert!(e.message.contains("foreach: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_foreach_extract_fanout_charged_independently_of_input_length() {
        // A single input element whose UPDATE fans out far past the
        // budget; each output gets its own EXTRACT eval (#695). Pins that
        // EXTRACT fanout is charged on its own — a design charging only
        // once per input element would never trip here, since there is
        // only one.
        query!(b"null", r"foreach (1) as $x (0; range(20000); .)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix.len(), REDUCE_FOREACH_MAX_STEPS - 1);
                assert!(e.message.contains("foreach: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_foreach_hoisted_extract_substitution_stays_aligned_per_input_val() {
        // Regression test for the #695 substitute_var hoist: EXTRACT must
        // see the *matching* input_val's substitution at each position
        // (via the idx-based lookup into the precomputed side array), not
        // a neighboring one.
        assert_eq!(
            outputs(b"null", "foreach (10,20,30) as $x (0; .+$x; [$x, .])"),
            ["[10,10]", "[20,30]", "[30,60]"]
        );
    }

    #[test]
    fn test_until_budget_exceeded_errors() {
        // `cond` is always falsy, so `until_step`'s single-output fast path
        // never emits anything before the `WHILE_UNTIL_MAX_STEPS` cap trips.
        query!(b"1", r"until(false; .)",
            QueryResult::Error(e) => {
                assert!(e.message.contains("until: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_until_forking_cond_propagates_update_error() {
        // A 2-output COND forces `until_step`'s forking (non-fast-path) branch;
        // the falsy output's UPDATE errors via `$nope`, which must propagate
        // immediately rather than being dropped once the loop over `cond_vals`
        // moves on.
        query!(b"1", r"until((true,false); $nope)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix, vec![OwnedValue::Int(1)]);
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    #[test]
    fn test_while_budget_exceeded_errors() {
        // `cond` is always truthy, so `while_step`'s single-output fast path
        // emits every step before the cap trips.
        query!(b"1", r"while(true; .)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix.len(), WHILE_UNTIL_MAX_STEPS);
                assert!(prefix.iter().all(|v| *v == OwnedValue::Int(1)));
                assert!(e.message.contains("while: maximum iterations exceeded"));
            }
        );
    }

    #[test]
    fn test_while_forking_cond_propagates_update_error() {
        // A 2-output COND forces `while_step`'s forking (non-fast-path) branch;
        // the first (truthy) output's UPDATE errors via `$nope`, which must
        // propagate immediately rather than being dropped once the loop over
        // `cond_vals` moves on.
        query!(b"1", r"while((true,true); $nope)",
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(prefix, vec![OwnedValue::Int(1)]);
                assert!(e.message.contains("undefined variable"));
            }
        );
    }

    /// `while`'s COND/UPDATE slots now accept a top-level comma (#534) —
    /// same fanout rule as `until` above.
    #[test]
    fn test_while_comma_slots() {
        // UPDATE-comma: forks the rest of the loop per output (verified
        // against jq 1.7.1: `0,1` — the `.+10` branch immediately fails
        // `cond` and contributes nothing further).
        assert_eq!(outputs(b"0", "while(.<2; .+1,.+10)"), ["0", "1"]);

        // COND-comma: matches the already-pinned `while_cond_forks` golden
        // case's shape (`tests/data/jq-golden/cases/while_cond_forks`), kept
        // here too as a fast, in-tree eval-level regression alongside it.
        assert_eq!(
            outputs(b"null", "[while((.<3,.<1); .+1)]"),
            [r"[null,1,2,null,1,2]"]
        );
    }

    #[test]
    fn test_repeat() {
        // repeat(expr) - repeatedly evaluate expr with original input
        // jq behavior: repeat(. * 2) on input 1 produces 2, 2, 2, ...
        query!(br"1", r"[limit(5; repeat(. * 2))]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                    OwnedValue::Int(2),
                ]);
            }
        );
    }

    #[test]
    fn test_repeat_identity() {
        // repeat(.) produces the same value infinitely
        query!(br#""hello""#, r"[limit(3; repeat(.))]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr, vec![
                    OwnedValue::String("hello".into()),
                    OwnedValue::String("hello".into()),
                    OwnedValue::String("hello".into()),
                ]);
            }
        );
    }

    #[test]
    fn test_recurse() {
        // Basic recurse with filter - collect all values recursively
        query!(br#"{"a": 1, "b": {"c": 2}}"#, r"[recurse | .a? // .c? // empty]",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                // Should contain the values 1 and 2
                assert!(arr.len() >= 2);
            }
        );
    }

    #[test]
    fn test_isvalid() {
        // isvalid returns true for valid expressions
        query!(br#"{"a": 1}"#, r"isvalid(.a)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        // isvalid returns true for missing field (returns null, not error)
        query!(br#"{"a": 1}"#, r"isvalid(.b)",
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );

        // isvalid returns false for actual error-producing expressions
        query!(br"123", r"isvalid(.foo)",
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[test]
    fn test_isvalid_reaches_every_builtins_own_optional_guard() {
        // `isvalid(EXPR)` is the one surviving construct that still evaluates
        // `EXPR` with `optional` forced `true` for the whole subtree
        // (`builtin_isvalid` does this deliberately, not by accident: without
        // it, a fork construct — comma/reduce/foreach — that errors partway
        // through would come back as `Partial`, which `isvalid`'s own
        // three-arm match doesn't special-case and would wrongly count as
        // "valid"). Every other route to `optional = true` was removed by
        // #693 — `E?`/`try E` now evaluate `E` with the *ambient* `optional`
        // and catch the aggregate result once via `eval_try`, rather than
        // broadcasting `true` down the whole subtree the way the pre-#693
        // bug did. That leaves each of these builtins' own internal
        // `_ if optional => ...` arm reachable only through `isvalid`, so
        // this is regression coverage for #698 (indirect coverage lost by
        // #693's fix, all of it real behavior — `isvalid` correctly
        // reporting `false` — not dead code): pin one case per remaining
        // caller so a future refactor can't silently make `isvalid` stop
        // noticing one of these error shapes.
        for expr in [
            "isvalid(.[])",
            "isvalid(keys)",
            "isvalid(keys_unsorted)",
            r#"isvalid(contains("a"))"#,
            r#"isvalid(inside("a"))"#,
            "isvalid(bsearch(2))",
        ] {
            query!(br"1", expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }

        // The `@format` builtins' own `_ if optional` arm is unlike the
        // others above: it doesn't produce `None`, it produces `Ok(String::
        // new())` — under `optional`, a value the format can't handle
        // renders as `""` rather than failing at all, so `isvalid` sees a
        // genuine success and reports `true`, not `false`.
        for expr in [
            "isvalid(@urid)",
            "isvalid(@csv)",
            "isvalid(@tsv)",
            r#"isvalid(@dsv("|"))"#,
            "isvalid(@base64)",
            "isvalid(@base64d)",
        ] {
            query!(br"1", expr,
                QueryResult::Owned(OwnedValue::Bool(true)) => {}
            );
        }

        // `error(...)` itself.
        query!(br"1", r#"isvalid(error("x"))"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );

        // Assignment/update/del: the write-time path traversal fails one
        // level down (`.a` is `1`, not an object, so `.b` can't be written
        // into it), and `set_path`/`update_path`/`delete_at_path` have no
        // `optional` of their own — it's `eval_assign`/`eval_update`/
        // `builtin_del`'s *own* ambient `optional` (forced by `isvalid`)
        // that decides whether the failure is swallowed.
        for expr in [
            "isvalid(.a.b = 5)",
            r#"isvalid(.a |= error("x"))"#,
            "isvalid(del(.a.b))",
        ] {
            query!(br#"{"a":1}"#, expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }

        // reduce/foreach: `limit(-1; 1)` errors unconditionally (it has no
        // `optional` arm of its own), so it's the one construct that can
        // still leak a genuine `Error`/`Partial` control past a leaf's own
        // self-suppression and into `eval_reduce`/`eval_foreach`/
        // `finish_fork`'s own optional-guards, one per INIT/SOURCE/fork-loop
        // site.
        for expr in [
            "isvalid(reduce (1,2) as $x (0; limit(-1;1)))",
            "isvalid(reduce (1,2) as $x (limit(-1;1); .+$x))",
            "isvalid(reduce (1,2) as $x ((1,limit(-1;1)); .+$x))",
            "isvalid(foreach limit(-1;1) as $x (0; .+$x))",
            "isvalid(foreach (1,2) as $x (limit(-1;1); .+$x))",
        ] {
            query!(br"1", expr,
                QueryResult::Owned(OwnedValue::Bool(false)) => {}
            );
        }
    }

