    #[test]
    fn test_null_literal() {
        query!(b"42", "null", QueryResult::Owned(OwnedValue::Null) => {});
    }

    #[test]
    fn test_modulemeta() {
        // modulemeta returns null (stub)
        query!(b"null", r#"modulemeta("test")"#, QueryResult::Owned(OwnedValue::Null) => {});
    }

    #[test]
    fn test_path_expr() {
        // path(expr) returns the path components to the value selected by expr
        query!(br#"{"a": 1, "b": 2}"#, "path(.a)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 1);
                assert_eq!(arr[0], OwnedValue::String("a".into()));
            }
        );

        // Test nested path
        query!(br#"{"a": {"b": {"c": 1}}}"#, "path(.a.b.c)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 3);
                assert_eq!(arr[0], OwnedValue::String("a".into()));
                assert_eq!(arr[1], OwnedValue::String("b".into()));
                assert_eq!(arr[2], OwnedValue::String("c".into()));
            }
        );

        // Test array index
        query!(br"[10, 20, 30]", "path(.[1])",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 1);
                assert_eq!(arr[0], OwnedValue::Int(1));
            }
        );

        // Test negative index (preserved as-is, matching jq)
        query!(br"[10, 20, 30]", "path(.[-1])",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert_eq!(arr.len(), 1);
                assert_eq!(arr[0], OwnedValue::Int(-1));
            }
        );

        // Test identity path
        query!(br#"{"a": 1}"#, "path(.)",
            QueryResult::Owned(OwnedValue::Array(arr)) => {
                assert!(arr.is_empty()); // Identity has no path components
            }
        );
    }

    /// "No paths at all" is no output — never the *root* path (#489).
    ///
    /// `[]` is a real answer: it is what `path(.)` returns, and the one path
    /// that always resolves. Rendering emptiness as it aimed a caller's
    /// `getpath`/`setpath`/`delpaths` at the document root, which is why this
    /// pins the variant (`None`) and not just the rendered output.
    #[test]
    fn test_path_of_nothing_is_no_output_not_the_root_path() {
        query!(br#"{"a": 1}"#, "path(empty)", QueryResult::None => {});
        // Both branches prune, so the comma composes to nothing at all.
        query!(br#""s""#, "path(.a?, .b?)", QueryResult::None => {});
        // The other direction, so a fix that returned `None` for everything
        // would not pass: an empty path is still an answer when it is meant.
        query!(br#"{"a": 1}"#, "path(.)",
            QueryResult::Owned(OwnedValue::Array(arr)) => assert!(arr.is_empty())
        );
    }

    /// A `?`-suppressed step that cannot resolve contributes *no component*.
    ///
    /// It used to leave its component behind — `"s" | path(.a?)` answered
    /// `["a"]`, a path into a string (#489). `?` is only an off switch for the
    /// step's error; a step that never happened names nothing.
    #[test]
    fn test_optional_step_that_cannot_resolve_names_no_path() {
        for filter in [
            "path(.a?)",
            "path(.[0]?)",
            "path(.[]?)",
            r#"path(.["a"]?)"#,
            "path((.a)?)",
            // `?` outside `path(...)` reaches the same walk, so it prunes too.
            "path(.a)?",
        ] {
            assert_eq!(outputs(br#""s""#, filter), Vec::<String>::new(), "{filter}");
        }
        // The suppression is per *value*, not per spelling: the same step on a
        // container it can index keeps its component.
        assert_eq!(outputs(br#"{"a": 1}"#, "path(.a?)"), [r#"["a"]"#]);
        assert_eq!(outputs(br"[1, 2]", "path(.[0]?)"), ["[0]"]);
    }

    /// A step *through* a missing key, a null, or an out-of-range index keeps
    /// the whole path — jq's `{"a":1} | path(.b.c)` is `["b","c"]` (#489).
    ///
    /// Reading a path is not walking one: `.b` on `{"a":1}` reads `null`, and
    /// `null` accepts a further step, so the path exists even though nothing
    /// is stored along it. This is what `setpath`'s auto-vivification consumes.
    #[test]
    fn test_path_survives_a_step_that_reads_null() {
        assert_eq!(outputs(br#"{"a": 1}"#, "path(.b.c)"), [r#"["b","c"]"#]);
        assert_eq!(outputs(br"{}", "path(.a.b)"), [r#"["a","b"]"#]);
        assert_eq!(outputs(br"null", "path(.a.b)"), [r#"["a","b"]"#]);
        assert_eq!(outputs(br"[1]", "path(.[3].x)"), [r#"[3,"x"]"#]);
        // Including under `?`, which suppresses errors and nothing else — a
        // step that reads `null` never errored in the first place.
        assert_eq!(outputs(br#"{"a": 1}"#, "path(.b.c?)"), [r#"["b","c"]"#]);
        assert_eq!(outputs(br"[1, 2]", "path(.[5]?)"), ["[5]"]);
    }

    /// Without `?`, a step that cannot index its value raises jq's own
    /// sentence rather than inventing a component for it (#489).
    ///
    /// The wording is not spelled here: it comes from the value evaluator, so
    /// `path(f)` reports exactly what `f` reports. `tests/jq_error_message_tests.rs`
    /// is what pins the text against real jq.
    #[test]
    fn test_unindexable_step_errors_instead_of_inventing_a_path() {
        for (json, filter, message) in [
            (
                &br#""s""#[..],
                "path(.a)",
                r#"Cannot index string with string "a""#,
            ),
            (
                &br#""s""#[..],
                "path(.[0])",
                "Cannot index string with number",
            ),
            (
                &br#"{"a": 1}"#[..],
                "path(.a.b)",
                r#"Cannot index number with string "b""#,
            ),
            (
                &br#"{"a": 1}"#[..],
                "path(.[0])",
                "Cannot index object with number",
            ),
            (
                &br#"{"a": 1}"#[..],
                "path(.[1:2])",
                "Cannot index object with object",
            ),
            (
                &br"[1, 2]"[..],
                "path(.a)",
                r#"Cannot index array with string "a""#,
            ),
            (
                &br#""s""#[..],
                "path(.[])",
                r#"Cannot iterate over string ("s")"#,
            ),
            (
                &br"null"[..],
                "path(.[])",
                "Cannot iterate over null (null)",
            ),
        ] {
            query!(json, filter,
                QueryResult::Error(e) => assert_eq!(e.message, message, "{filter}")
            );
        }
    }

    /// #483: shapes `resolve_node` already knew how to resolve, but that
    /// `needs_path_prepass`'s old whitelist never routed to it, plus the
    /// combinators added alongside the fix (`first`, `if`, `//`, `limit`,
    /// `try`, `label`, `as`, static `getpath`). Every expectation here is
    /// captured from real jq 1.7.1 and mirrored as a golden fixture under
    /// `tests/data/jq-golden/cases/path_*`.
    #[test]
    fn test_path_resolves_recursive_descent_recurse_select_and_typeof() {
        let doc = br#"{"a":{"b":1},"c":2}"#;
        assert_eq!(
            outputs(doc, "[path(..)]"),
            [r#"[[],["a"],["a","b"],["c"]]"#]
        );
        assert_eq!(
            outputs(doc, "[path(recurse)]"),
            [r#"[[],["a"],["a","b"],["c"]]"#]
        );
        assert_eq!(
            outputs(doc, "[path(.. | numbers)]"),
            [r#"[["a","b"],["c"]]"#]
        );
        assert_eq!(
            outputs(doc, r#"[path(.[] | select(type=="number"))]"#),
            [r#"[["c"]]"#]
        );
        // The write-side operators share the same resolver, so they now
        // succeed instead of refusing these same shapes outright.
        query!(doc, "(.. | numbers) = 9",
            QueryResult::Owned(v) => assert_eq!(v.to_json(), r#"{"a":{"b":9},"c":9}"#)
        );
        query!(doc, "del(.. | numbers)",
            QueryResult::Owned(v) => assert_eq!(v.to_json(), r#"{"a":{}}"#)
        );
    }

    #[test]
    fn test_path_resolves_transparent_control_flow_combinators() {
        let doc = br#"{"a":{"b":1},"c":[1,2]}"#;
        assert_eq!(outputs(doc, "[path(first(.a,.c))]"), [r#"[["a"]]"#]);
        assert_eq!(
            outputs(doc, "[path(if true then .a else .c end)]"),
            [r#"[["a"]]"#]
        );
        assert_eq!(outputs(doc, "[path(.a // .c)]"), [r#"[["a"]]"#]);
        assert_eq!(outputs(doc, "[path(limit(1; .a))]"), [r#"[["a"]]"#]);
        assert_eq!(outputs(doc, "[path(try .a)]"), [r#"[["a"]]"#]);
        assert_eq!(outputs(doc, "[path(label $out | .a)]"), [r#"[["a"]]"#]);
        assert_eq!(outputs(doc, "[path(.a as $x | .c)]"), [r#"[["c"]]"#]);
        assert_eq!(outputs(doc, r#"[path(getpath(["a"]))]"#), [r#"[["a"]]"#]);
    }

    /// #530: a filter that is not a path expression at all — as opposed to
    /// one jq recognises but this resolver does not (#483) — raises jq's own
    /// sentence by name instead of answering `[]`.
    #[test]
    // `"path({a:1})"` is a jq filter literal, not a formatting string; clippy
    // cannot tell the two apart from the brace shape alone.
    #[allow(clippy::literal_string_with_formatting_args)]
    fn test_path_of_a_non_path_expression_raises_invalid_path_expression() {
        for (filter, message) in [
            ("path(1)", "Invalid path expression with result 1"),
            ("path(length)", "Invalid path expression with result 1"),
            ("path(keys)", r#"Invalid path expression with result ["a"]"#),
            ("path(.a + 1)", "Invalid path expression with result 2"),
            (
                "path(.a | tostring)",
                r#"Invalid path expression with result "1""#,
            ),
            (
                "path({a:1})",
                r#"Invalid path expression with result {"a":1}"#,
            ),
        ] {
            query!(br#"{"a":1}"#, filter,
                QueryResult::Error(e) => assert_eq!(e.message, message, "{filter}")
            );
        }
    }

    /// `?` does not suppress `invalid_path_expression` — it is a statement
    /// about the filter, not a value error raised while collecting a path
    /// (confirmed live against jq 1.7.1: `path(("a")?)` still raises there).
    /// `try` (with or without a `catch`) is the same rule under its other
    /// spelling.
    #[test]
    fn test_invalid_path_expression_survives_optional_and_try() {
        for filter in ["path((\"a\")?)", "path(try 1)", "path(try 1 catch \"x\")"] {
            query!(br#"{"a":1}"#, filter,
                QueryResult::Error(e) => {
                    assert!(e.is_invalid_path_expression(), "{filter}: {}", e.message);
                }
            );
        }
    }

    /// #530's sibling fix: `path()` streams every output its argument
    /// produces as it resolves them, so a later sibling erroring does not
    /// erase an earlier one that already succeeded — jq's own generator
    /// semantics never "un-emit" an output. Verified against jq 1.7.1:
    /// `path(.a, 1)` prints `["a"]` then raises; `(.a, .b[0])?` prints
    /// `["a"]` and silently stops.
    #[test]
    fn test_path_keeps_the_prefix_before_a_later_sibling_errors() {
        query!(br#"{"a":1}"#, "path(.a, 1)",
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#"["a"]"#]);
                assert_eq!(e.message, "Invalid path expression with result 1");
            }
        );
        query!(br#"{"a":1,"b":"x"}"#, "path(.a, .b[0])",
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#"["a"]"#]);
                assert_eq!(e.message, "Cannot index string with number");
            }
        );
        // `?` keeps the same prefix but swallows the error entirely.
        assert_eq!(
            outputs(br#"{"a":1,"b":"x"}"#, "[path((.a, .b[0])?)]"),
            [r#"[["a"]]"#]
        );
        // `=`/`|=`/`del()` stay atomic: jq resolves every path against the
        // original document before writing any of them, so one bad sibling
        // means nothing is written at all — no partial prefix here.
        query!(br#"{"a":1}"#, "(.a, 1) = 5",
            QueryResult::Error(e) => assert_eq!(e.message, "Invalid path expression with result 1")
        );
    }

    /// #832: `resolve_catch` (shared by `resolve_node`'s `Expr::Try` arm's
    /// `Error` and `Break` cases) used a bare `?` on the catch handler's own
    /// resolution, discarding `prefix` -- whatever the failed `try` body had
    /// already resolved -- the instant the handler itself failed, instead of
    /// threading it into the returned `Err` the way every sibling arm here
    /// does (e.g. `test_path_keeps_the_prefix_before_a_later_sibling_errors`
    /// above). Ordinary-error variant: the handler's own output (`"x"`) is
    /// not a valid path expression (#530's gate). Verified against jq 1.7.1:
    /// `path(try (.a, .x[0]) catch "x")` on `{"a":1,"x":5}` prints `["a"]`
    /// (the `.a` branch, resolved before `.x[0]` failed) then raises
    /// "Invalid path expression with result \"x\"", exit 5.
    #[test]
    fn test_path_try_catch_handler_error_keeps_prefix_832() {
        query!(br#"{"a":1,"x":5}"#, r#"path(try (.a, .x[0]) catch "x")"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#"["a"]"#]);
                assert!(e.is_invalid_path_expression(), "{}", e.message);
            }
        );
    }

    /// #832, break variant: the same `resolve_catch` helper is reached via
    /// the `Expr::Try` arm's `Break` case (rather than its `Error` case
    /// above) once `catch` intercepts a `break` (#824, #562's "catch catches
    /// break the same way it catches error" rule) -- and the handler itself
    /// then raises an ordinary error. Verified against jq 1.7.1: `label $out
    /// | path(try (.a, break $out) catch error("y"))` on `{"a":1}` prints
    /// `["a"]` then raises "y", exit 5.
    #[test]
    fn test_path_try_catch_handler_break_keeps_prefix_832() {
        query!(
            br#"{"a":1}"#,
            r#"label $out | path(try (.a, break $out) catch error("y"))"#,
            QueryResult::Partial(vs, Control::Error(e)) => {
                assert_eq!(prefix_json(&vs), [r#"["a"]"#]);
                assert_eq!(e.message, "y");
            }
        );
    }

    #[test]
    fn test_paths_filter() {
        // paths(filter) streams paths where values match filter
        query!(br#"{"a": 1, "b": "hello", "c": 2}"#, "paths(type == \"number\")",
            QueryResult::ManyOwned(paths) => {
                // Should have paths to "a" and "c" (both numbers)
                assert_eq!(paths.len(), 2);
                assert_eq!(paths[0], OwnedValue::Array(vec![OwnedValue::String("a".into())]));
                assert_eq!(paths[1], OwnedValue::Array(vec![OwnedValue::String("c".into())]));
            }
        );
    }

